            let max_words = match evaluate_expression(executor, &args[1], row)? {
                Value::Integer(i) => i.max(0) as usize,
                _ => return Ok(Value::Null),
            };
            let words: Vec<&str> = s.split_whitespace().take(max_words).collect();
            Ok(Value::String(words.join(" ")))
