            let digits: String = s.chars().filter(|c| c.is_ascii_digit()).collect();
            let valid_chars = s
                .chars()
                .all(|c| c.is_ascii_digit() || " ()-+.".contains(c));
            Ok(Value::Bool(
                valid_chars && digits.len() >= 7 && digits.len() <= 15,
            ))
