            let rotated: String = s
                .chars()
                .map(|c| match c {
                    'a'..='z' => (((c as u8 - b'a' + shift) % 26) + b'a') as char,
                    'A'..='Z' => (((c as u8 - b'A' + shift) % 26) + b'A') as char,
                    _ => c,
                })
                .collect();
            Ok(Value::String(rotated))
