            let (y2, m2, _) = cal_parse_ymd(&d2)
                .ok_or_else(|| PieskieoError::Internal("DATE_DIFF_MONTHS: invalid date2".into()))?;
            let months = (y2 as i64 - y1 as i64) * 12 + (m2 as i64 - m1 as i64);
            Ok(Value::Integer(months))
