            let result: std::collections::HashMap<String, Value> = obj
                .into_iter()
                .filter_map(|(k, v)| {
                    let new_key = match &v {
                        Value::String(s) => Some(s.clone()),
                        Value::Integer(i) => Some(i.to_string()),
                        _ => None,
                    };
                    new_key.map(|nk| (nk, Value::String(k)))
                })
                .collect();
            Ok(Value::Object(result))
