            let lon1 = value_to_f64(&evaluate_expression(executor, &args[1], row)?);
            let lat2 = value_to_f64(&evaluate_expression(executor, &args[2], row)?);
            let lon2 = value_to_f64(&evaluate_expression(executor, &args[3], row)?);
