            match evaluate_expression(executor, &args[0], row)? {
                Value::Null => Ok(Value::Null),
                Value::String(s) => {
                    let mut freq: std::collections::BTreeMap<char, i64> =
                        std::collections::BTreeMap::new();
                    for c in s.chars() {
                        *freq.entry(c).or_insert(0) += 1;
                    }
                    let map: HashMap<String, Value> = freq
                        .into_iter()
                        .map(|(c, n)| (c.to_string(), Value::Integer(n)))
                        .collect();
                    Ok(Value::Object(map))
                }
                _ => Ok(Value::Null),
            }
