            let schema = evaluate_expression(executor, &args[1], row)?;
            match (obj, schema) {
                (Value::Object(obj_map), Value::Object(schema_map)) => {
                    for (field, type_val) in &schema_map {
                        let expected_type = match type_val {
                            Value::String(s) => s.as_str(),
                            _ => return Ok(Value::Bool(false)),
                        };
                        let actual_val = obj_map.get(field).unwrap_or(&Value::Null);
                        let type_ok = match expected_type {
                            "null" => matches!(actual_val, Value::Null),
                            "bool" => matches!(actual_val, Value::Bool(_)),
                            "integer" => matches!(actual_val, Value::Integer(_)),
                            "float" => matches!(actual_val, Value::Float(_)),
                            "string" => matches!(actual_val, Value::String(_)),
                            "uuid" => matches!(actual_val, Value::Uuid(_)),
                            "array" => matches!(actual_val, Value::Array(_)),
                            "object" => matches!(actual_val, Value::Object(_)),
                            "vector" => matches!(actual_val, Value::Vector(_)),
                            "number" => matches!(actual_val, Value::Integer(_) | Value::Float(_)),
                            _ => false,
                        };
                        if !type_ok {
                            return Ok(Value::Bool(false));
                        }
                    }
                    Ok(Value::Bool(true))
                }
                _ => Ok(Value::Bool(false)),
            }
