            let ea = match evaluate_expression(executor, &args[1], row)? {
                Value::Integer(i) => i as f64,
                Value::Float(f) => f,
                _ => return Ok(Value::Null),
            };
            let t = match evaluate_expression(executor, &args[2], row)? {
                Value::Integer(i) => i as f64,
                Value::Float(f) => f,
                _ => return Ok(Value::Null),
            };
            if t == 0.0 {
                return Ok(Value::Null);
            }
            const R: f64 = 8.314;
            Ok(Value::Float(a * (-ea / (R * t)).exp()))
