fn seq_isoelectric_point(seq: &str) -> f64 {
    let d_c = seq.chars().filter(|&c| c == 'D').count() as f64;
    let e_c = seq.chars().filter(|&c| c == 'E').count() as f64;
    let h_c = seq.chars().filter(|&c| c == 'H').count() as f64;
    let c_c = seq.chars().filter(|&c| c == 'C').count() as f64;
    let y_c = seq.chars().filter(|&c| c == 'Y').count() as f64;
    let k_c = seq.chars().filter(|&c| c == 'K').count() as f64;
    let r_c = seq.chars().filter(|&c| c == 'R').count() as f64;
    let mut lo = 0.0f64;
    let mut hi = 14.0f64;
    for _ in 0..100 {
        let ph = (lo + hi) / 2.0;
        let pos = 1.0 / (1.0 + 10f64.powf(ph - 8.0))
            + h_c / (1.0 + 10f64.powf(ph - 6.0))
            + k_c / (1.0 + 10f64.powf(ph - 10.5))
            + r_c / (1.0 + 10f64.powf(ph - 12.5));
        let neg = 1.0 / (1.0 + 10f64.powf(3.1 - ph))
            + d_c / (1.0 + 10f64.powf(3.9 - ph))
            + e_c / (1.0 + 10f64.powf(4.1 - ph))
            + c_c / (1.0 + 10f64.powf(8.3 - ph))
            + y_c / (1.0 + 10f64.powf(10.1 - ph));
        if pos - neg > 0.0 {
            lo = ph;
        } else {
            hi = ph;
        }
    }
    (lo + hi) / 2.0
}

