fn seq_find_orfs(dna: &str) -> Vec<Value> {
    let mut orfs = vec![];
    let forward: Vec<char> = dna.chars().collect();
    let rev_comp: String = forward
        .iter()
        .rev()
        .map(|&c| match c {
            'A' => 'T',
            'T' => 'A',
            'G' => 'C',
            'C' => 'G',
            o => o,
        })
        .collect();
    let rev_chars: Vec<char> = rev_comp.chars().collect();
    let strands: [(&[char], bool, i64); 2] = [
        (forward.as_slice(), true, 1i64),
        (rev_chars.as_slice(), false, -1i64),
    ];
    for (seq, is_forward, strand_sign) in &strands {
        for frame in 0..3usize {
            let mut i = frame;
            while i + 2 < seq.len() {
                let codon: String = seq[i..i + 3].iter().collect();
                if codon == "ATG" {
                    let orf_start = i;
                    let mut j = i + 3;
                    let mut found_stop = false;
                    while j + 2 < seq.len() {
                        let sc: String = seq[j..j + 3].iter().collect();
                        if sc == "TAA" || sc == "TAG" || sc == "TGA" {
                            let orf_len = j + 3 - orf_start;
                            if orf_len >= 30 {
                                let orf_seq: String = seq[orf_start..j + 3].iter().collect();
                                let pos = if *is_forward {
                                    orf_start as i64
                                } else {
                                    (seq.len() - j - 3) as i64
                                };
                                let mut obj = std::collections::HashMap::new();
                                obj.insert(
                                    "frame".to_string(),
                                    Value::Integer((frame as i64 + 1) * strand_sign),
                                );
                                obj.insert("position".to_string(), Value::Integer(pos));
                                obj.insert("length".to_string(), Value::Integer(orf_len as i64));
                                obj.insert("sequence".to_string(), Value::String(orf_seq));
                                orfs.push(Value::Object(obj));
                            }
                            found_stop = true;
                            break;
                        }
                        j += 3;
                    }
                    if found_stop {
                        i += 3;
                        continue;
                    }
                }
                i += 3;
            }
        }
    }
    orfs
}

// ── Time-series private helpers ───────────────────────────────────────────────

/// Holt double exponential smoothing. Returns (final_level, final_trend, smoothed_array).
fn ts_double_exp_smooth(nums: &[f64], alpha: f64, beta: f64) -> (f64, f64, Vec<f64>) {
    let n = nums.len();
    if n < 2 {
        return (nums[0], 0.0, nums.to_vec());
    }
    let mut level = nums[0];
    let mut trend = nums[1] - nums[0];
    let mut smoothed = Vec::with_capacity(n);
    smoothed.push(level + trend);
    for &x in &nums[1..] {
        let prev_level = level;
        level = alpha * x + (1.0 - alpha) * (level + trend);
        trend = beta * (level - prev_level) + (1.0 - beta) * trend;
        smoothed.push(level + trend);
    }
    (level, trend, smoothed)
}

/// Holt-Winters additive triple exponential smoothing. Returns fitted values.
fn ts_triple_exp_smooth(
    nums: &[f64],
    alpha: f64,
    beta: f64,
    gamma: f64,
    period: usize,
) -> Vec<f64> {
    let n = nums.len();
    if n < period * 2 {
        return nums.to_vec();
    }
    // Initialize level as mean of first period
    let l0: f64 = nums[..period].iter().sum::<f64>() / period as f64;
    // Initialize trend as average difference across first two periods
    let t0: f64 = (0..period)
        .map(|i| (nums[i + period] - nums[i]) / period as f64)
        .sum::<f64>()
        / period as f64;
    // Initialize seasonal indices
    let mut seasonal: Vec<f64> = (0..period).map(|i| nums[i] - l0).collect();
    let mut level = l0;
    let mut trend = t0;
    let mut fitted = Vec::with_capacity(n);
    for i in 0..n {
        let s_idx = i % period;
        if i == 0 {
            fitted.push(level + trend + seasonal[s_idx]);
            continue;
        }
        let prev_level = level;
        level = alpha * (nums[i] - seasonal[s_idx]) + (1.0 - alpha) * (level + trend);
        trend = beta * (level - prev_level) + (1.0 - beta) * trend;
        seasonal[s_idx] = gamma * (nums[i] - level) + (1.0 - gamma) * seasonal[s_idx];
        fitted.push(level + trend + seasonal[s_idx]);
    }
    fitted
}

/// Centered moving average for trend estimation.
fn ts_centered_ma(nums: &[f64], period: usize) -> Vec<f64> {
    let n = nums.len();
    let half = period / 2;
    (0..n)
        .map(|i| {
            let lo = if i >= half { i - half } else { 0 };
            let hi = (i + half + 1).min(n);
            let slice = &nums[lo..hi];
            slice.iter().sum::<f64>() / slice.len() as f64
        })
        .collect()
}

/// Hodrick-Prescott filter via gradient descent (approximate for small n).
fn ts_hp_filter(nums: &[f64], lambda: f64) -> Vec<f64> {
    let n = nums.len();
    // Use gradient descent to minimize HP objective
    let mut tau = nums.to_vec();
    for _iter in 0..200 {
        let mut grad = vec![0.0f64; n];
        for i in 0..n {
            grad[i] += 2.0 * (tau[i] - nums[i]);
        }
        // Second-difference penalty gradient
        for i in 2..n {
            let d2 = tau[i] - 2.0 * tau[i - 1] + tau[i - 2];
            grad[i] += 2.0 * lambda * d2;
            grad[i - 1] -= 4.0 * lambda * d2;
            grad[i - 2] += 2.0 * lambda * d2;
        }
        let step = 0.01 / (1.0 + 2.0 * lambda);
        for i in 0..n {
            tau[i] -= step * grad[i];
        }
    }
    tau
}

/// Partial autocorrelation via Yule-Walker equations (Levinson-Durbin).
fn ts_pacf(nums: &[f64], max_lag: usize) -> Vec<f64> {
    let n = nums.len();
    if n < 2 {
        return vec![1.0];
    }
    let mean = nums.iter().sum::<f64>() / n as f64;
    let var: f64 = nums.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / n as f64;
    if var == 0.0 {
        return (0..=max_lag)
            .map(|k| if k == 0 { 1.0 } else { 0.0 })
            .collect();
    }
    // Compute autocovariances r[0..max_lag]
    let max_k = max_lag.min(n - 1);
    let r: Vec<f64> = (0..=max_k)
        .map(|k| {
            (0..n - k)
                .map(|i| (nums[i] - mean) * (nums[i + k] - mean))
                .sum::<f64>()
                / n as f64
                / var
        })
        .collect();

    // Levinson-Durbin recursion
    let mut pacf = vec![1.0f64; max_k + 1];
    if max_k == 0 {
        return pacf;
    }
    pacf[1] = r[1];
    let mut phi_prev = vec![r[1]];
    for k in 2..=max_k {
        // phi_k_k = (r[k] - sum(phi_prev[j] * r[k-1-j], j=0..k-1)) / (1 - sum(phi_prev[j] * r[j+1], j=0..k-1))
        let num: f64 = r[k]
            - phi_prev
                .iter()
                .enumerate()
                .map(|(j, &p)| p * r[k - 1 - j])
                .sum::<f64>();
        let den: f64 = 1.0
            - phi_prev
                .iter()
                .enumerate()
                .map(|(j, &p)| p * r[j + 1])
                .sum::<f64>();
        let phi_kk = if den.abs() < 1e-12 { 0.0 } else { num / den };
        pacf[k] = phi_kk;
        let mut phi_new = vec![0.0f64; k];
        for j in 0..k - 1 {
            phi_new[j] = phi_prev[j] - phi_kk * phi_prev[k - 2 - j];
        }
        phi_new[k - 1] = phi_kk;
        phi_prev = phi_new;
    }
    pacf
}

/// AR(p) model fitting via OLS on lagged values.
fn ts_ar_fit(nums: &[f64], p: usize) -> Vec<f64> {
    let n = nums.len();
    if n <= p {
        return vec![0.0; p];
    }
    // Build design matrix X (n-p) x p and target y
    let rows = n - p;
    let mut xt_x = vec![vec![0.0f64; p]; p];
    let mut xt_y = vec![0.0f64; p];
    for t in 0..rows {
        let y_t = nums[t + p];
        for i in 0..p {
            xt_y[i] += nums[t + p - 1 - i] * y_t;
            for j in 0..p {
                xt_x[i][j] += nums[t + p - 1 - i] * nums[t + p - 1 - j];
            }
        }
    }
    // Solve via Gaussian elimination
    ts_solve_linear(&mut xt_x, &mut xt_y, p)
}

/// Simple Gaussian elimination to solve Ax = b. Returns x.
fn ts_solve_linear(a: &mut Vec<Vec<f64>>, b: &mut Vec<f64>, n: usize) -> Vec<f64> {
    for col in 0..n {
        // Partial pivot
        let pivot = (col..n).max_by(|&r1, &r2| {
            a[r1][col]
                .abs()
                .partial_cmp(&a[r2][col].abs())
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        if let Some(p) = pivot {
            a.swap(col, p);
            b.swap(col, p);
        }
        let pivot_val = a[col][col];
        if pivot_val.abs() < 1e-12 {
            continue;
        }
        for row in (col + 1)..n {
            let factor = a[row][col] / pivot_val;
            for c in col..n {
                a[row][c] -= factor * a[col][c];
            }
            b[row] -= factor * b[col];
        }
    }
    // Back substitution
    let mut x = vec![0.0f64; n];
    for i in (0..n).rev() {
        let mut s = b[i];
        for j in (i + 1)..n {
            s -= a[i][j] * x[j];
        }
        x[i] = if a[i][i].abs() < 1e-12 {
            0.0
        } else {
            s / a[i][i]
        };
    }
    x
}

/// Approximate chi-squared p-value (survival function) for Q with df degrees of freedom.
fn ts_chi2_p_approx(q: f64, df: usize) -> f64 {
    if q <= 0.0 {
        return 1.0;
    }
    if df == 0 {
        return 0.0;
    }
    // Wilson-Hilferty normal approximation of chi-squared CDF
    let k = df as f64;
    let z = ((q / k).powf(1.0 / 3.0) - (1.0 - 2.0 / (9.0 * k))) / (2.0 / (9.0 * k)).sqrt();
    // P(Z > z) = 1 - Phi(z)
    let t = 1.0 / (1.0 + 0.2316419 * z.abs());
    let d = 0.3989423 * (-z * z / 2.0).exp();
    let poly =
        t * (0.3193815 + t * (-0.3565638 + t * (1.7814779 + t * (-1.8212560 + t * 1.3302744))));
    let phi_z = 1.0 - d * poly;
    if z >= 0.0 {
        1.0 - phi_z
    } else {
        phi_z
    }
}

// ── Number theory private helpers (nt_ prefix) ───────────────────────────────

/// Extended Euclidean algorithm: returns (gcd, x, y) such that a*x + b*y = gcd
fn nt_extended_gcd(a: i64, b: i64) -> (i64, i64, i64) {
    if b == 0 {
        return (a.abs(), if a >= 0 { 1 } else { -1 }, 0);
    }
    let (g, x1, y1) = nt_extended_gcd(b, a % b);
    (g, y1, x1 - (a / b) * y1)
}

/// Fast modular exponentiation: (base^exp) % modulus
fn nt_mod_pow(base: i64, mut exp: u64, modulus: i64) -> i64 {
    if modulus == 1 {
        return 0;
    }
    let m = modulus as i128;
    let mut result = 1i128;
    let mut b = ((base % modulus) as i128 + m) % m;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * b % m;
        }
        b = b * b % m;
        exp >>= 1;
    }
    result as i64
}

/// Integer power without modulus (saturating)
fn nt_ipow(base: i64, exp: u64) -> i64 {
    let mut result = 1i64;
    let mut b = base;
    let mut e = exp;
    while e > 0 {
        if e & 1 == 1 {
            result = result.saturating_mul(b);
        }
        b = b.saturating_mul(b);
        e >>= 1;
    }
    result
}

/// Chinese Remainder Theorem: solve x ≡ r[i] (mod m[i]) for all i
fn nt_crt(rs: &[i64], ms: &[i64]) -> Option<i64> {
    let mut x = rs[0];
    let mut step = ms[0];
    for i in 1..rs.len() {
        let r = rs[i];
        let m = ms[i];
        // Find x such that x ≡ r (mod m) and x ≡ current solution
        // x = current_x + step * t, need step*t ≡ r - x (mod m)
        let diff = ((r - x) % m + m) % m;
        let (g, inv, _) = nt_extended_gcd(step % m, m);
        if diff % g != 0 {
            return None;
        } // no solution
        let new_step = step * (m / g);
        let t = (diff / g * ((inv % (m / g) + m / g) % (m / g))) % (m / g);
        x = x + step * t;
        step = new_step;
        x = ((x % step) + step) % step;
    }
    Some(x)
}

/// Euler totient function phi(n)
fn nt_totient(n: i64) -> i64 {
    if n <= 0 {
        return 0;
    }
    let mut result = n as f64;
    let mut m = n;
    let mut p = 2i64;
    while p * p <= m {
        if m % p == 0 {
            while m % p == 0 {
                m /= p;
            }
            result *= 1.0 - 1.0 / p as f64;
        }
        p += 1;
    }
    if m > 1 {
        result *= 1.0 - 1.0 / m as f64;
    }
    result.round() as i64
}

/// Find smallest primitive root modulo prime p
fn nt_primitive_root(p: i64) -> Option<i64> {
    if p == 2 {
        return Some(1);
    }
    if !is_prime_func(p) {
        return None;
    }
    // Factorize p-1
    let phi = p - 1;
    let factors: Vec<i64> = {
        let mut f = Vec::new();
        let mut n = phi;
        let mut d = 2i64;
        while d * d <= n {
            if n % d == 0 {
                f.push(d);
                while n % d == 0 {
                    n /= d;
                }
            }
            d += 1;
        }
        if n > 1 {
            f.push(n);
        }
        f
    };
    for g in 2..p {
        let mut is_root = true;
        for &q in &factors {
            if nt_mod_pow(g, (phi / q) as u64, p) == 1 {
                is_root = false;
                break;
            }
        }
        if is_root {
            return Some(g);
        }
    }
    None
}

/// Baby-step giant-step: find x such that a^x ≡ b (mod m)
fn nt_baby_step_giant_step(a: i64, b: i64, m: i64) -> Option<i64> {
    use std::collections::HashMap as HM;
    let n = (m as f64).sqrt().ceil() as i64 + 1;
    // Baby steps: store a^j -> j for j in 0..n
    let mut table = HM::new();
    let mut cur = b % m;
    for j in 0..n {
        table.insert(cur, j);
        cur = cur * (a % m) % m;
    }
    // Giant steps: a^(n*i) for i in 0..n, check if in table
    let factor = nt_mod_pow(a, n as u64, m);
    let mut cur = factor;
    for i in 1..=n {
        if let Some(&j) = table.get(&cur) {
            let x = i * n - j;
            if x >= 0 {
                return Some(x);
            }
        }
        cur = cur * factor % m;
    }
    None
}

/// Binomial coefficient C(n, k) using multiplicative formula
fn nt_binomial(n: u64, k: u64) -> u64 {
    if k > n {
        return 0;
    }
    let k = k.min(n - k);
    let mut result = 1u64;
    for i in 0..k {
        result = result.saturating_mul(n - i) / (i + 1);
    }
    result
}

/// Euler numbers E(n) for even n up to max_n via recurrence
fn nt_euler_numbers(max_n: usize) -> Vec<i64> {
    // E numbers via zigzag triangle (tangent/secant numbers)
    // E(0)=1, E(2)=-1, E(4)=5, E(6)=-61, E(8)=1385, E(10)=-50521
    let known: Vec<i64> = vec![
        1,
        0,
        -1,
        0,
        5,
        0,
        -61,
        0,
        1385,
        0,
        -50521,
        0,
        2702765,
        0,
        -199360981,
        0,
        19391512145,
        0,
        -2404879675441,
        0,
        370371188237525,
    ];
    let mut result = vec![0i64; max_n + 1];
    for i in 0..=(max_n.min(known.len() - 1)) {
        result[i] = known[i];
    }
    result
}

/// Bernoulli number B(n) as f64 via recurrence
fn nt_bernoulli(n: usize) -> f64 {
    // Known values for efficiency
    match n {
        0 => 1.0,
        1 => -0.5,
        2 => 1.0 / 6.0,
        4 => -1.0 / 30.0,
        6 => 1.0 / 42.0,
        8 => -1.0 / 30.0,
        10 => 5.0 / 66.0,
        12 => -691.0 / 2730.0,
        14 => 7.0 / 6.0,
        16 => -3617.0 / 510.0,
        18 => 43867.0 / 798.0,
        20 => -174611.0 / 330.0,
        _ if n % 2 != 0 => 0.0, // B(n)=0 for odd n>1
        _ => {
            // Compute via recurrence: sum(C(n+1,k)*B(k) for k=0..n-1) + B(n)*(n+1) = 0
            let mut b = vec![0.0f64; n + 1];
            b[0] = 1.0;
            if n >= 1 {
                b[1] = -0.5;
            }
            for m in 2..=n {
                if m % 2 != 0 {
                    b[m] = 0.0;
                    continue;
                }
                let mut sum = 0.0f64;
                for k in 0..m {
                    let c = nt_binomial(m as u64 + 1, k as u64) as f64;
                    sum += c * b[k];
                }
                b[m] = -sum / (m as f64 + 1.0);
            }
            b[n]
        }
    }
}

/// Tangent number T(n) for odd n
fn nt_tangent_number(n: usize) -> i64 {
    // T(1)=1, T(3)=2, T(5)=16, T(7)=272, T(9)=7936, T(11)=353792, T(13)=22368256
    // T(15)=1903757312, T(17)=209865342976, T(19)=29088885112832
    match n {
        1 => 1,
        3 => 2,
        5 => 16,
        7 => 272,
        9 => 7936,
        11 => 353792,
        13 => 22368256,
        15 => 1903757312,
        17 => 209865342976,
        19 => 29088885112832,
        _ => 0,
    }
}

// ── Aggregate/group stubs (pending full group-by implementation) ──────────────

/// Basic aggregation helper for scalar values.
fn opt_aggregate_basic(name: &str, values: &[Value]) -> Value {
    let nums: Vec<f64> = values
        .iter()
        .filter_map(|v| match v {
            Value::Float(f) => Some(*f),
            Value::Integer(i) => Some(*i as f64),
            _ => None,
        })
        .collect();
    match name.to_uppercase().as_str() {
        "SUM" => Value::Float(nums.iter().sum()),
        "AVG" => {
            if nums.is_empty() {
                Value::Null
            } else {
                Value::Float(nums.iter().sum::<f64>() / nums.len() as f64)
            }
        }
        "COUNT" => Value::Integer(values.len() as i64),
        "MIN" => nums
            .iter()
            .cloned()
            .reduce(f64::min)
            .map(Value::Float)
            .unwrap_or(Value::Null),
        "MAX" => nums
            .iter()
            .cloned()
            .reduce(f64::max)
            .map(Value::Float)
            .unwrap_or(Value::Null),
        _ => Value::Null,
    }
}

// ── Optimization private helpers ──────────────────────────────────────────────

fn opt_knapsack_01(weights: &[usize], values: &[i64], cap: usize, n: usize) -> (i64, Vec<usize>) {
    let mut dp = vec![vec![0i64; cap + 1]; n + 1];
    for i in 1..=n {
        for c in 0..=cap {
            dp[i][c] = dp[i - 1][c];
            if weights[i - 1] <= c {
                let take = dp[i - 1][c - weights[i - 1]] + values[i - 1];
                if take > dp[i][c] {
                    dp[i][c] = take;
                }
            }
        }
    }
    let max_val = dp[n][cap];
    let mut taken = Vec::new();
    let mut c = cap;
    for i in (1..=n).rev() {
        if dp[i][c] != dp[i - 1][c] {
            taken.push(i - 1);
            c -= weights[i - 1];
        }
    }
    taken.sort();
    (max_val, taken)
}

fn opt_hungarian(cost: &[Vec<f64>], n: usize) -> (f64, Vec<usize>) {
    let big = 1e18f64;
    let mut u = vec![0.0f64; n + 1];
    let mut v = vec![0.0f64; n + 1];
    let mut p = vec![0usize; n + 1];
    let mut way = vec![0usize; n + 1];
    for i in 1..=n {
        p[0] = i;
        let mut j0 = 0usize;
        let mut minval = vec![big; n + 1];
        let mut used = vec![false; n + 1];
        loop {
            used[j0] = true;
            let i0 = p[j0];
            let mut delta = big;
            let mut j1 = 0usize;
            for j in 1..=n {
                if !used[j] {
                    let cur = cost
                        .get(i0 - 1)
                        .and_then(|r| r.get(j - 1))
                        .copied()
                        .unwrap_or(big)
                        - u[i0]
                        - v[j];
                    if cur < minval[j] {
                        minval[j] = cur;
                        way[j] = j0;
                    }
                    if minval[j] < delta {
                        delta = minval[j];
                        j1 = j;
                    }
                }
            }
            for j in 0..=n {
                if used[j] {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minval[j] -= delta;
                }
            }
            j0 = j1;
            if p[j0] == 0 {
                break;
            }
        }
        while j0 != 0 {
            p[j0] = p[way[j0]];
            j0 = way[j0];
        }
    }
    let mut assignment = vec![0usize; n];
    for j in 1..=n {
        if p[j] != 0 {
            assignment[p[j] - 1] = j - 1;
        }
    }
    let total_cost: f64 = (0..n)
        .map(|i| {
            cost.get(i)
                .and_then(|r| r.get(assignment[i]))
                .copied()
                .unwrap_or(0.0)
        })
        .sum();
    (total_cost, assignment)
}

fn opt_lp_2var(
    c1: f64,
    c2: f64,
    constraints: &[(f64, f64, f64)],
    maximize: bool,
) -> (f64, f64, f64) {
    let mut candidates: Vec<(f64, f64)> = vec![(0.0, 0.0)];
    for &(a1, _a2, b) in constraints {
        if a1 > 1e-12 {
            let x1 = b / a1;
            if x1 >= -1e-9 {
                candidates.push((x1, 0.0));
            }
        }
    }
    for &(_a1, a2, b) in constraints {
        if a2 > 1e-12 {
            let x2 = b / a2;
            if x2 >= -1e-9 {
                candidates.push((0.0, x2));
            }
        }
    }
    for i in 0..constraints.len() {
        for j in (i + 1)..constraints.len() {
            let (a1, a2, b1) = constraints[i];
            let (c1c, c2c, b2) = constraints[j];
            let det = a1 * c2c - a2 * c1c;
            if det.abs() > 1e-12 {
                let x1 = (b1 * c2c - a2 * b2) / det;
                let x2 = (a1 * b2 - b1 * c1c) / det;
                if x1 >= -1e-9 && x2 >= -1e-9 {
                    candidates.push((x1, x2));
                }
            }
        }
    }
    let feasible: Vec<(f64, f64)> = candidates
        .into_iter()
        .filter(|&(x1, x2)| {
            x1 >= -1e-9
                && x2 >= -1e-9
                && constraints
                    .iter()
                    .all(|&(a1, a2, b)| a1 * x1 + a2 * x2 <= b + 1e-9)
        })
        .collect();
    if feasible.is_empty() {
        return (0.0, 0.0, 0.0);
    }
    let best = feasible.iter().copied().max_by(|&(x1a, x2a), &(x1b, x2b)| {
        let oa = c1 * x1a + c2 * x2a;
        let ob = c1 * x1b + c2 * x2b;
        if maximize {
            oa.partial_cmp(&ob).unwrap_or(std::cmp::Ordering::Equal)
        } else {
            ob.partial_cmp(&oa).unwrap_or(std::cmp::Ordering::Equal)
        }
    });
    match best {
        Some((x1, x2)) => (x1, x2, c1 * x1 + c2 * x2),
        None => (0.0, 0.0, 0.0),
    }
}

fn opt_graph_to_adj(graph_val: &Value) -> (usize, Vec<Vec<bool>>) {
    match graph_val {
        Value::Array(rows) => {
            let n = rows.len();
            let adj: Vec<Vec<bool>> = rows
                .iter()
                .map(|r| match r {
                    Value::Array(row_inner) => row_inner
                        .iter()
                        .map(|v| match v {
                            Value::Bool(b) => *b,
                            Value::Integer(i) => *i != 0,
                            Value::Float(f) => *f != 0.0,
                            _ => false,
                        })
                        .collect(),
                    _ => vec![false; n],
                })
                .collect();
            (n, adj)
        }
        Value::Object(m) => {
            let n = m.len();
            let mut adj = vec![vec![false; n]; n];
            for (k, v) in m {
                let from: usize = k.parse().unwrap_or(0);
                if let Value::Array(neighbors) = v {
                    for nb in neighbors {
                        let to = match nb {
                            Value::Integer(i) => *i as usize,
                            Value::Float(f) => *f as usize,
                            _ => continue,
                        };
                        if from < n && to < n {
                            adj[from][to] = true;
                            adj[to][from] = true;
                        }
                    }
                }
            }
            (n, adj)
        }
        _ => (0, vec![]),
    }
}

/// Convert a Value reference to a Vec<f64> wrapped in Some, or None if not array/vector.
fn val_to_f64_vec(v: &Value) -> Option<Vec<f64>> {
    match v {
        Value::Array(arr) => Some(arr.iter().map(value_to_f64).collect()),
        Value::Vector(vv) => Some(vv.iter().map(|x| *x as f64).collect()),
        _ => None,
    }
}

// ── String similarity private helpers ────────────────────────────────────────

/// Levenshtein edit distance between two strings.
fn levenshtein_distance(a: &str, b: &str) -> usize {
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let (m, n) = (a_chars.len(), b_chars.len());
    let mut dp = vec![vec![0usize; n + 1]; m + 1];
    for i in 0..=m {
        dp[i][0] = i;
    }
    for j in 0..=n {
        dp[0][j] = j;
    }
    for i in 1..=m {
        for j in 1..=n {
            let cost = if a_chars[i - 1] == b_chars[j - 1] {
                0
            } else {
                1
            };
            dp[i][j] = (dp[i - 1][j] + 1)
                .min(dp[i][j - 1] + 1)
                .min(dp[i - 1][j - 1] + cost);
        }
    }
    dp[m][n]
}

/// Damerau-Levenshtein distance (includes transpositions).
fn damerau_levenshtein_distance(a: &str, b: &str) -> usize {
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let (m, n) = (a_chars.len(), b_chars.len());
    let mut dp = vec![vec![0usize; n + 1]; m + 1];
    for i in 0..=m {
        dp[i][0] = i;
    }
    for j in 0..=n {
        dp[0][j] = j;
    }
    for i in 1..=m {
        for j in 1..=n {
            let cost = if a_chars[i - 1] == b_chars[j - 1] {
                0
            } else {
                1
            };
            dp[i][j] = (dp[i - 1][j] + 1)
                .min(dp[i][j - 1] + 1)
                .min(dp[i - 1][j - 1] + cost);
            if i > 1
                && j > 1
                && a_chars[i - 1] == b_chars[j - 2]
                && a_chars[i - 2] == b_chars[j - 1]
            {
                dp[i][j] = dp[i][j].min(dp[i - 2][j - 2] + cost);
            }
        }
    }
    dp[m][n]
}

/// Jaro-Winkler similarity (0.0 to 1.0).
fn jaro_winkler(s1: &str, s2: &str) -> f64 {
    if s1 == s2 {
        return 1.0;
    }
    let s1c: Vec<char> = s1.chars().collect();
    let s2c: Vec<char> = s2.chars().collect();
    let (l1, l2) = (s1c.len(), s2c.len());
    if l1 == 0 || l2 == 0 {
        return 0.0;
    }
    let match_dist = (l1.max(l2) / 2).saturating_sub(1);
    let mut s1_matches = vec![false; l1];
    let mut s2_matches = vec![false; l2];
    let mut matches = 0usize;
    let mut transpositions = 0usize;
    for i in 0..l1 {
        let lo = if i > match_dist { i - match_dist } else { 0 };
        let hi = (i + match_dist + 1).min(l2);
        for j in lo..hi {
            if s2_matches[j] || s1c[i] != s2c[j] {
                continue;
            }
            s1_matches[i] = true;
            s2_matches[j] = true;
            matches += 1;
            break;
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut k = 0;
    for i in 0..l1 {
        if !s1_matches[i] {
            continue;
        }
        while !s2_matches[k] {
            k += 1;
        }
        if s1c[i] != s2c[k] {
            transpositions += 1;
        }
        k += 1;
    }
    let jaro = (matches as f64 / l1 as f64
        + matches as f64 / l2 as f64
        + (matches - transpositions / 2) as f64 / matches as f64)
        / 3.0;
    let prefix = s1c
        .iter()
        .zip(s2c.iter())
        .take(4)
        .take_while(|(a, b)| a == b)
        .count();
    jaro + prefix as f64 * 0.1 * (1.0 - jaro)
}

/// Soundex encoding for English words.
fn soundex(s: &str) -> String {
    let s = s.to_uppercase();
    let chars: Vec<char> = s.chars().filter(|c| c.is_ascii_alphabetic()).collect();
    if chars.is_empty() {
        return "0000".to_string();
    }
    let code_for = |c: char| -> char {
        match c {
            'B' | 'F' | 'P' | 'V' => '1',
            'C' | 'G' | 'J' | 'K' | 'Q' | 'S' | 'X' | 'Z' => '2',
            'D' | 'T' => '3',
            'L' => '4',
            'M' | 'N' => '5',
            'R' => '6',
            _ => '0',
        }
    };
    let first = chars[0];
    let mut result = String::from(first);
    let mut prev_code = code_for(first);
    for &c in &chars[1..] {
        let code = code_for(c);
        if code != '0' && code != prev_code {
            result.push(code);
            if result.len() == 4 {
                break;
            }
        }
        if code != '0' {
            prev_code = code;
        }
    }
    while result.len() < 4 {
        result.push('0');
    }
    result
}

/// Convert a Unix timestamp (seconds) to (year, month, day) tuple.
fn chrono_to_parts(ts: i64) -> (i64, i64, i64) {
    // Days since Unix epoch
    let days = ts / 86400;
    // Zeller's algorithm approximation
    let z = days + 719468;
    let era = (if z >= 0 { z } else { z - 146096 }) / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

/// Create a simple text embedding (bag of words hash -> fixed-length vector).
/// Returns a Value::Vector with 16 floats.
fn embed_text(text: &str) -> Value {
    let mut vec = vec![0.0f32; 16];
    for (i, c) in text.bytes().enumerate() {
        vec[i % 16] += c as f32 / 255.0;
    }
    let mag: f32 = vec.iter().map(|x| x * x).sum::<f32>().sqrt().max(1e-6);
    for x in &mut vec {
        *x /= mag;
    }
    Value::Vector(vec)
}

// ── Statistical testing private helpers ──────────────────────────────────────

fn stat_to_f64_vec(v: Value) -> Vec<f64> {
    match v {
        Value::Array(arr) => arr.iter().map(value_to_f64).collect(),
        Value::Vector(vv) => vv.iter().map(|x| *x as f64).collect(),
        _ => vec![],
    }
}

fn stat_pearson_r(xs: &[f64], ys: &[f64]) -> f64 {
    let n = xs.len().min(ys.len());
    if n < 2 {
        return 0.0;
    }
    let mean_x = xs[..n].iter().sum::<f64>() / n as f64;
    let mean_y = ys[..n].iter().sum::<f64>() / n as f64;
    let num: f64 = (0..n).map(|i| (xs[i] - mean_x) * (ys[i] - mean_y)).sum();
    let den_x: f64 = xs[..n]
        .iter()
        .map(|x| (x - mean_x).powi(2))
        .sum::<f64>()
        .sqrt();
    let den_y: f64 = ys[..n]
        .iter()
        .map(|y| (y - mean_y).powi(2))
        .sum::<f64>()
        .sqrt();
    if den_x == 0.0 || den_y == 0.0 {
        0.0
    } else {
        num / (den_x * den_y)
    }
}

fn stat_rank_vec(xs: &[f64]) -> Vec<f64> {
    let n = xs.len();
    let mut indexed: Vec<(usize, f64)> = xs.iter().cloned().enumerate().collect();
    indexed.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal));
    let mut ranks = vec![0.0f64; n];
    let mut i = 0;
    while i < n {
        let mut j = i;
        while j < n && indexed[j].1 == indexed[i].1 {
            j += 1;
        }
        let avg_rank = (i + j + 1) as f64 / 2.0;
        for k in i..j {
            ranks[indexed[k].0] = avg_rank;
        }
        i = j;
    }
    ranks
}

fn stat_ols_slope_intercept(xs: &[f64], ys: &[f64]) -> (f64, f64) {
    let n = xs.len().min(ys.len());
    if n < 2 {
        return (0.0, 0.0);
    }
    let mean_x = xs[..n].iter().sum::<f64>() / n as f64;
    let mean_y = ys[..n].iter().sum::<f64>() / n as f64;
    let num: f64 = (0..n).map(|i| (xs[i] - mean_x) * (ys[i] - mean_y)).sum();
    let den: f64 = xs[..n].iter().map(|x| (x - mean_x).powi(2)).sum();
    if den == 0.0 {
        return (0.0, mean_y);
    }
    let slope = num / den;
    let intercept = mean_y - slope * mean_x;
    (slope, intercept)
}

fn stat_normal_cdf(z: f64) -> f64 {
    let t = 1.0 / (1.0 + 0.2316419 * z.abs());
    let d = 0.3989423 * (-z * z / 2.0).exp();
    let poly =
        t * (0.3193815 + t * (-0.3565638 + t * (1.7814779 + t * (-1.8212560 + t * 1.3302744))));
    let p = 1.0 - d * poly;
    if z >= 0.0 {
        p
    } else {
        1.0 - p
    }
}

fn stat_normal_p_two_tailed(z: f64) -> f64 {
    let z = z.abs();
    let t = 1.0 / (1.0 + 0.2316419 * z);
    let d = 0.3989423 * (-z * z / 2.0).exp();
    let poly =
        t * (0.3193815 + t * (-0.3565638 + t * (1.7814779 + t * (-1.8212560 + t * 1.3302744))));
    (2.0 * d * poly).min(1.0)
}

fn stat_normal_quantile(p: f64) -> f64 {
    let p = p.clamp(1e-12, 1.0 - 1e-12);
    let t = if p < 0.5 {
        (-2.0 * p.ln()).sqrt()
    } else {
        (-2.0 * (1.0 - p).ln()).sqrt()
    };
    let c0 = 2.515517_f64;
    let c1 = 0.802853_f64;
    let c2 = 0.010328_f64;
    let d1 = 1.432788_f64;
    let d2 = 0.189269_f64;
    let d3 = 0.001308_f64;
    let q = t - (c0 + c1 * t + c2 * t * t) / (1.0 + d1 * t + d2 * t * t + d3 * t * t * t);
    if p < 0.5 {
        -q
    } else {
        q
    }
}

fn stat_t_p_approx(t: f64, df: f64) -> f64 {
    let z = if df > 30.0 {
        t
    } else {
        t * (1.0 - 1.0 / (4.0 * df))
    };
    stat_normal_p_two_tailed(z)
}

fn stat_chi2_p_approx(chi2: f64, df: f64) -> f64 {
    if chi2 <= 0.0 || df <= 0.0 {
        return 1.0;
    }
    let mu = 1.0 - 2.0 / (9.0 * df);
    let sigma2 = 2.0 / (9.0 * df);
    if sigma2 <= 0.0 {
        return 1.0;
    }
    let z = ((chi2 / df).powf(1.0 / 3.0) - mu) / sigma2.sqrt();
    1.0 - stat_normal_cdf(z)
}

fn stat_gauss_solve(a: &[Vec<f64>], b: &[f64]) -> Vec<f64> {
    let n = b.len();
    if n == 0 {
        return vec![];
    }
    let mut mat: Vec<Vec<f64>> = a
        .iter()
        .zip(b.iter())
        .map(|(row, &bi)| {
            let mut r = row.clone();
            r.push(bi);
            r
        })
        .collect();
    for col in 0..n {
        let mut max_row = col;
        for row_i in (col + 1)..n {
            if mat[row_i][col].abs() > mat[max_row][col].abs() {
                max_row = row_i;
            }
        }
        mat.swap(col, max_row);
        let pivot = mat[col][col];
        if pivot.abs() < 1e-12 {
            continue;
        }
        for row_i in (col + 1)..n {
            let factor = mat[row_i][col] / pivot;
            for k in col..=n {
                mat[row_i][k] -= factor * mat[col][k];
            }
        }
    }
    let mut x = vec![0.0f64; n];
    for i in (0..n).rev() {
        let mut sum = mat[i][n];
        for j in (i + 1)..n {
            sum -= mat[i][j] * x[j];
        }
        x[i] = if mat[i][i].abs() < 1e-12 {
            0.0
        } else {
            sum / mat[i][i]
        };
    }
    x
}

fn value_to_f64(v: &Value) -> f64 {
    match v {
        Value::Integer(i) => *i as f64,
        Value::Float(f) => *f,
        Value::Bool(b) => {
            if *b {
                1.0
            } else {
                0.0
            }
        }
        _ => 0.0,
    }
}

fn literal_to_value(lit: &crate::pql::ast::Literal) -> Value {
    use crate::pql::ast::Literal;
    match lit {
        Literal::Null => Value::Null,
        Literal::Bool(b) => Value::Bool(*b),
        Literal::Integer(i) => Value::Integer(*i),
        Literal::Float(f) => Value::Float(*f),
        Literal::String(s) => Value::String(s.clone()),
        Literal::Uuid(u) => Value::Uuid(*u),
    }
}

fn get_nested_field(row: &super::Row, path: &[String]) -> Value {
    if path.is_empty() {
        return Value::Null;
    }
    let mut current = row.data.get(&path[0]).cloned().unwrap_or(Value::Null);
    for key in &path[1..] {
        match current {
            Value::Object(ref obj) => {
                current = obj.get(key).cloned().unwrap_or(Value::Null);
            }
            _ => return Value::Null,
        }
    }
    current
}

fn apply_comparison(op: crate::pql::ast::ComparisonOp, left: &Value, right: &Value) -> bool {
    use crate::pql::ast::ComparisonOp;
    match op {
        ComparisonOp::Equal => left == right,
        ComparisonOp::NotEqual => left != right,
        ComparisonOp::LessThan => compare_values(left, right) == std::cmp::Ordering::Less,
        ComparisonOp::LessThanEqual => {
            let cmp = compare_values(left, right);
            cmp == std::cmp::Ordering::Less || cmp == std::cmp::Ordering::Equal
        }
        ComparisonOp::GreaterThan => compare_values(left, right) == std::cmp::Ordering::Greater,
        ComparisonOp::GreaterThanEqual => {
            let cmp = compare_values(left, right);
            cmp == std::cmp::Ordering::Greater || cmp == std::cmp::Ordering::Equal
        }
        ComparisonOp::Like => {
            if let (Value::String(s), Value::String(pattern)) = (left, right) {
                s.contains(pattern.trim_matches('%'))
            } else {
                false
            }
        }
        ComparisonOp::Contains => {
            if let (Value::String(s), Value::String(substr)) = (left, right) {
                s.contains(substr.as_str())
            } else {
                false
            }
        }
        ComparisonOp::NotLike => {
            if let (Value::String(s), Value::String(pattern)) = (left, right) {
                !s.contains(pattern.trim_matches('%'))
            } else {
                true
            }
        }
        ComparisonOp::ILike => {
            if let (Value::String(s), Value::String(pattern)) = (left, right) {
                s.to_lowercase()
                    .contains(&pattern.trim_matches('%').to_lowercase())
            } else {
                false
            }
        }
        ComparisonOp::RegexMatch => {
            if let (Value::String(s), Value::String(pattern)) = (left, right) {
                RegexObj::new(pattern)
                    .map(|re| re.is_match(s))
                    .unwrap_or(false)
            } else {
                false
            }
        }
        ComparisonOp::NotContains => {
            if let (Value::String(s), Value::String(substr)) = (left, right) {
                !s.contains(substr.as_str())
            } else {
                true
            }
        }
    }
}

fn apply_binary_op(
    op: crate::pql::ast::BinaryOperator,
    left: Value,
    right: Value,
) -> Result<Value> {
    use crate::pql::ast::BinaryOperator;
    match op {
        BinaryOperator::Add => match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a + b)),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a + b)),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Float(a as f64 + b)),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Float(a + b as f64)),
            (Value::String(a), Value::String(b)) => Ok(Value::String(a + &b)),
            _ => Ok(Value::Null),
        },
        BinaryOperator::Subtract => match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a - b)),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a - b)),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Float(a as f64 - b)),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Float(a - b as f64)),
            _ => Ok(Value::Null),
        },
        BinaryOperator::Multiply => match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a * b)),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a * b)),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Float(a as f64 * b)),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Float(a * b as f64)),
            _ => Ok(Value::Null),
        },
        BinaryOperator::Divide => match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => {
                if b == 0 {
                    Ok(Value::Null)
                } else {
                    Ok(Value::Integer(a / b))
                }
            }
            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a / b)),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Float(a as f64 / b)),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Float(a / b as f64)),
            _ => Ok(Value::Null),
        },
        BinaryOperator::Modulo => match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => {
                if b == 0 {
                    Ok(Value::Null)
                } else {
                    Ok(Value::Integer(a % b))
                }
            }
            _ => Ok(Value::Null),
        },
        BinaryOperator::Power => match (left, right) {
            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a.powf(b))),
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Float((a as f64).powf(b as f64))),
            (Value::Integer(a), Value::Float(b)) => Ok(Value::Float((a as f64).powf(b))),
            (Value::Float(a), Value::Integer(b)) => Ok(Value::Float(a.powf(b as f64))),
            _ => Ok(Value::Null),
        },
        BinaryOperator::Concat => match (left, right) {
            (Value::String(a), Value::String(b)) => Ok(Value::String(a + &b)),
            _ => Ok(Value::Null),
        },
        BinaryOperator::BitwiseAnd => match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a & b)),
            _ => Ok(Value::Null),
        },
        BinaryOperator::BitwiseOr => match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a | b)),
            _ => Ok(Value::Null),
        },
        BinaryOperator::BitwiseXor => match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a ^ b)),
            _ => Ok(Value::Null),
        },
        BinaryOperator::ShiftLeft => match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a << (b & 63))),
            _ => Ok(Value::Null),
        },
        BinaryOperator::ShiftRight => match (left, right) {
            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a >> (b & 63))),
            _ => Ok(Value::Null),
        },
    }
}

fn apply_unary_op(op: crate::pql::ast::UnaryOperator, operand: Value) -> Result<Value> {
    use crate::pql::ast::UnaryOperator;
    match op {
        UnaryOperator::Negate => match operand {
            Value::Integer(i) => Ok(Value::Integer(-i)),
            Value::Float(f) => Ok(Value::Float(-f)),
            _ => Ok(Value::Null),
        },
        UnaryOperator::Not => match operand {
            Value::Bool(b) => Ok(Value::Bool(!b)),
            _ => Ok(Value::Null),
        },
        UnaryOperator::BitwiseNot => match operand {
            Value::Integer(i) => Ok(Value::Integer(!i)),
            _ => Ok(Value::Null),
        },
    }
}

#[inline(always)]
fn phys_big_g() -> f64 {
    6.674e-11
}

pub(crate) fn values_equal(a: &Value, b: &Value) -> bool {
    matches!(compare_values(a, b), std::cmp::Ordering::Equal)
}

pub fn compare_values(left: &Value, right: &Value) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    match (left, right) {
        (Value::Null, Value::Null) => Ordering::Equal,
        (Value::Null, _) => Ordering::Less,
        (_, Value::Null) => Ordering::Greater,
        (Value::Bool(a), Value::Bool(b)) => a.cmp(b),
        (Value::Integer(a), Value::Integer(b)) => a.cmp(b),
        (Value::Float(a), Value::Float(b)) => a.partial_cmp(b).unwrap_or(Ordering::Equal),
        (Value::Integer(a), Value::Float(b)) => {
            (*a as f64).partial_cmp(b).unwrap_or(Ordering::Equal)
        }
        (Value::Float(a), Value::Integer(b)) => {
            a.partial_cmp(&(*b as f64)).unwrap_or(Ordering::Equal)
        }
        (Value::String(a), Value::String(b)) => a.cmp(b),
        _ => Ordering::Equal,
    }
}

fn lcg_rand(state: &mut u64) -> u64 {
    *state = state
        .wrapping_mul(6364136223846793005)
        .wrapping_add(1442695040888963407);
    *state >> 33
}

/// Convert RGB (0-255 each) to HSL. Returns (h 0-360, s 0-1, l 0-1).
fn rgb_to_hsl_fn(r: f64, g: f64, b: f64) -> (f64, f64, f64) {
    let rn = r / 255.0;
    let gn = g / 255.0;
    let bn = b / 255.0;
    let max = rn.max(gn).max(bn);
    let min = rn.min(gn).min(bn);
    let l = (max + min) / 2.0;
    if (max - min).abs() < 1e-10 {
        return (0.0, 0.0, l);
    }
    let d = max - min;
    let s = if l > 0.5 {
        d / (2.0 - max - min)
    } else {
        d / (max + min)
    };
    let h = if max == rn {
        (gn - bn) / d + if gn < bn { 6.0 } else { 0.0 }
    } else if max == gn {
        (bn - rn) / d + 2.0
    } else {
        (rn - gn) / d + 4.0
    } / 6.0;
    (h * 360.0, s, l)
}

/// Convert HSL (h 0-360, s 0-1, l 0-1) to RGB (0-255 each as u8).
fn hsl_to_rgb_fn(h: f64, s: f64, l: f64) -> (u8, u8, u8) {
    if s == 0.0 {
        let v = (l * 255.0).round() as u8;
        return (v, v, v);
    }
    fn hue_to_rgb(p: f64, q: f64, t: f64) -> f64 {
        let t = t.rem_euclid(1.0);
        if t < 1.0 / 6.0 {
            return p + (q - p) * 6.0 * t;
        }
        if t < 0.5 {
            return q;
        }
        if t < 2.0 / 3.0 {
            return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
        }
        p
    }
    let q = if l < 0.5 {
        l * (1.0 + s)
    } else {
        l + s - l * s
    };
    let p = 2.0 * l - q;
    let r = hue_to_rgb(p, q, h / 360.0 + 1.0 / 3.0);
    let g = hue_to_rgb(p, q, h / 360.0);
    let b = hue_to_rgb(p, q, h / 360.0 - 1.0 / 3.0);
    (
        (r * 255.0).round() as u8,
        (g * 255.0).round() as u8,
        (b * 255.0).round() as u8,
    )
}

// ── Color space private helpers ───────────────────────────────────────────────

/// Convert RGB (0-255 each) to HSV. Returns (h 0-360, s 0-1, v 0-1).
fn color_rgb_to_hsv(r: f64, g: f64, b: f64) -> (f64, f64, f64) {
    let rn = r / 255.0;
    let gn = g / 255.0;
    let bn = b / 255.0;
    let max = rn.max(gn).max(bn);
    let min = rn.min(gn).min(bn);
    let delta = max - min;
    let v = max;
    let s = if max == 0.0 { 0.0 } else { delta / max };
    let h = if delta == 0.0 {
        0.0
    } else if max == rn {
        let h = 60.0 * ((gn - bn) / delta);
        if h < 0.0 {
            h + 360.0
        } else {
            h
        }
    } else if max == gn {
        60.0 * ((bn - rn) / delta + 2.0)
    } else {
        60.0 * ((rn - gn) / delta + 4.0)
    };
    (h, s, v)
}

/// Convert HSV (h 0-360, s 0-1, v 0-1) to RGB (0-255 each).
fn color_hsv_to_rgb(h: f64, s: f64, v: f64) -> (u8, u8, u8) {
    if s == 0.0 {
        let c = (v * 255.0).round() as u8;
        return (c, c, c);
    }
    let h = h % 360.0;
    let hi = (h / 60.0) as u32;
    let f = h / 60.0 - hi as f64;
    let p = v * (1.0 - s);
    let q = v * (1.0 - s * f);
    let t = v * (1.0 - s * (1.0 - f));
    let (r, g, b) = match hi {
        0 => (v, t, p),
        1 => (q, v, p),
        2 => (p, v, t),
        3 => (p, q, v),
        4 => (t, p, v),
        _ => (v, p, q),
    };
    (
        (r * 255.0).round() as u8,
        (g * 255.0).round() as u8,
        (b * 255.0).round() as u8,
    )
}

/// Convert RGB (0-255 each) to CMYK (all 0-1).
fn color_rgb_to_cmyk(r: f64, g: f64, b: f64) -> (f64, f64, f64, f64) {
    let rn = r / 255.0;
    let gn = g / 255.0;
    let bn = b / 255.0;
    let k = 1.0 - rn.max(gn).max(bn);
    if (1.0 - k).abs() < 1e-10 {
        return (0.0, 0.0, 0.0, 1.0);
    }
    let c = (1.0 - rn - k) / (1.0 - k);
    let m = (1.0 - gn - k) / (1.0 - k);
    let y = (1.0 - bn - k) / (1.0 - k);
    (c.max(0.0), m.max(0.0), y.max(0.0), k.max(0.0))
}

/// Convert CMYK (all 0-1) to RGB (0-255 each).
fn color_cmyk_to_rgb(c: f64, m: f64, y: f64, k: f64) -> (u8, u8, u8) {
    let r = (255.0 * (1.0 - c) * (1.0 - k)).round() as u8;
    let g = (255.0 * (1.0 - m) * (1.0 - k)).round() as u8;
    let b = (255.0 * (1.0 - y) * (1.0 - k)).round() as u8;
    (r, g, b)
}

/// Convert RGB (0-255 each) to CIE XYZ (D65 reference white, simple gamma 2.2).
fn color_rgb_to_xyz(r: f64, g: f64, b: f64) -> (f64, f64, f64) {
    let rn = (r / 255.0).powf(2.2);
    let gn = (g / 255.0).powf(2.2);
    let bn = (b / 255.0).powf(2.2);
    let x = 0.4124564 * rn + 0.3575761 * gn + 0.1804375 * bn;
    let y = 0.2126729 * rn + 0.7151522 * gn + 0.0721750 * bn;
    let z = 0.0193339 * rn + 0.1191920 * gn + 0.9503041 * bn;
    (x * 100.0, y * 100.0, z * 100.0)
}

/// Convert CIE XYZ to CIE LAB (D65 reference white).
fn color_xyz_to_lab(x: f64, y: f64, z: f64) -> (f64, f64, f64) {
    let xn = 95.047;
    let yn = 100.0;
    let zn = 108.883;
    let f = |t: f64| -> f64 {
        if t > 0.008856 {
            t.powf(1.0 / 3.0)
        } else {
            7.787 * t + 16.0 / 116.0
        }
    };
    let fx = f(x / xn);
    let fy = f(y / yn);
    let fz = f(z / zn);
    let l = 116.0 * fy - 16.0;
    let a = 500.0 * (fx - fy);
    let bv = 200.0 * (fy - fz);
    (l, a, bv)
}

// ── ML clustering private helpers (mlc_ prefix) ──────────────────────────────

/// Find index of nearest centroid using Euclidean distance.
fn mlc_nearest_centroid(pt: &[f64], centroids: &[Vec<f64>]) -> usize {
    centroids
        .iter()
        .enumerate()
        .map(|(i, c)| (i, euclidean_dist_clustering(pt, c)))
        .min_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
        .map(|(i, _)| i)
        .unwrap_or(0)
}

/// Recompute centroids from data and cluster assignments.
fn mlc_update_centroids(data: &[Vec<f64>], labels: &[usize], k: usize) -> Vec<Vec<f64>> {
    if data.is_empty() {
        return vec![];
    }
    let dim = data[0].len();
    (0..k)
        .map(|ci| {
            let pts: Vec<&Vec<f64>> = data
                .iter()
                .zip(labels.iter())
                .filter(|(_, &l)| l == ci)
                .map(|(p, _)| p)
                .collect();
            if pts.is_empty() {
                vec![0.0; dim]
            } else {
                (0..dim)
                    .map(|d| pts.iter().map(|p| p[d]).sum::<f64>() / pts.len() as f64)
                    .collect()
            }
        })
        .collect()
}

/// Parse a Value::Array of Arrays into a Vec<Vec<f64>> distance matrix.
fn mlc_parse_dist_matrix(v: &Value) -> Vec<Vec<f64>> {
    match v {
        Value::Array(rows) => rows
            .iter()
            .map(|row| match row {
                Value::Array(cols) => cols.iter().map(value_to_f64).collect(),
                _ => vec![],
            })
            .collect(),
        _ => vec![],
    }
}

/// Hierarchical clustering returning array of merge step objects.
/// linkage: "single", "complete", or "average"
fn mlc_hierarchical_linkage(dm: &[Vec<f64>], linkage: &str) -> Value {
    let n = dm.len();
    if n < 2 {
        return Value::Array(vec![]);
    }
    let mut clusters: Vec<Vec<usize>> = (0..n).map(|i| vec![i]).collect();
    let mut dists: Vec<Vec<f64>> = dm.to_vec();
    let mut steps: Vec<Value> = Vec::new();

    for _ in 0..(n - 1) {
        let nc = clusters.len();
        if nc < 2 {
            break;
        }
        let mut best_dist = f64::INFINITY;
        let mut best_i = 0usize;
        let mut best_j = 1usize;
        for i in 0..nc {
            for j in (i + 1)..nc {
                if dists[i][j] < best_dist {
                    best_dist = dists[i][j];
                    best_i = i;
                    best_j = j;
                }
            }
        }
        let ci_rep = clusters[best_i][0];
        let cj_rep = clusters[best_j][0];
        let new_size = clusters[best_i].len() + clusters[best_j].len();
        let mut step_obj = HashMap::new();
        step_obj.insert("i".to_string(), Value::Integer(ci_rep as i64));
        step_obj.insert("j".to_string(), Value::Integer(cj_rep as i64));
        step_obj.insert("distance".to_string(), Value::Float(best_dist));
        step_obj.insert("size".to_string(), Value::Integer(new_size as i64));
        steps.push(Value::Object(step_obj));

        let merged_j = clusters.remove(best_j);
        clusters[best_i].extend(merged_j);

        dists.remove(best_j);
        for row in dists.iter_mut() {
            row.remove(best_j);
        }

        let new_nc = dists.len();
        for k in 0..new_nc {
            if k == best_i {
                continue;
            }
            let d_new = match linkage {
                "single" => clusters[best_i]
                    .iter()
                    .flat_map(|&a| clusters[k].iter().map(move |&b| dm[a][b]))
                    .fold(f64::INFINITY, f64::min),
                "complete" => clusters[best_i]
                    .iter()
                    .flat_map(|&a| clusters[k].iter().map(move |&b| dm[a][b]))
                    .fold(0.0_f64, f64::max),
                _ => {
                    let vals: Vec<f64> = clusters[best_i]
                        .iter()
                        .flat_map(|&a| clusters[k].iter().map(move |&b| dm[a][b]))
                        .collect();
                    if vals.is_empty() {
                        0.0
                    } else {
                        vals.iter().sum::<f64>() / vals.len() as f64
                    }
                }
            };
            dists[best_i][k] = d_new;
            dists[k][best_i] = d_new;
        }
    }
    Value::Array(steps)
}

/// Flat clustering using complete linkage via Union-Find.
fn mlc_cut_tree_complete(dm: &[Vec<f64>], n_clusters: usize) -> Vec<usize> {
    let n = dm.len();
    if n == 0 {
        return vec![];
    }
    if n_clusters >= n {
        return (0..n).collect();
    }
    let mut parent: Vec<usize> = (0..n).collect();
    fn find(p: &mut Vec<usize>, x: usize) -> usize {
        if p[x] != x {
            p[x] = find(p, p[x]);
        }
        p[x]
    }
    let mut active_count = n;

    while active_count > n_clusters {
        // Get current cluster roots
        let roots: Vec<usize> = {
            let mut seen = std::collections::HashSet::new();
            (0..n)
                .filter_map(|x| {
                    let r = find(&mut parent, x);
                    if seen.insert(r) {
                        Some(r)
                    } else {
                        None
                    }
                })
                .collect()
        };
        let nr = roots.len();
        if nr <= n_clusters {
            break;
        }

        // Complete linkage: find pair of clusters with minimum max-distance
        let mut best = f64::INFINITY;
        let mut bi = 0usize;
        let mut bj = 0usize;
        for ii in 0..nr {
            for jj in (ii + 1)..nr {
                let ri = roots[ii];
                let rj = roots[jj];
                let mut members_i: Vec<usize> = Vec::new();
                for x in 0..n {
                    if find(&mut parent, x) == ri {
                        members_i.push(x);
                    }
                }
                let mut members_j: Vec<usize> = Vec::new();
                for x in 0..n {
                    if find(&mut parent, x) == rj {
                        members_j.push(x);
                    }
                }
                let d = members_i
                    .iter()
                    .flat_map(|&a| members_j.iter().map(move |&b| dm[a][b]))
                    .fold(0.0_f64, f64::max);
                if d < best {
                    best = d;
                    bi = ri;
                    bj = rj;
                }
            }
        }
        // Merge bj -> bi
        for x in 0..n {
            if find(&mut parent, x) == bj {
                parent[x] = bi;
            }
        }
        for x in 0..n {
            let _ = find(&mut parent, x);
        }
        active_count -= 1;
    }

    let mut label_map: HashMap<usize, usize> = HashMap::new();
    let mut next_label = 0usize;
    let mut result_labels: Vec<usize> = Vec::with_capacity(n);
    for x in 0..n {
        let root = find(&mut parent, x);
        let lbl = *label_map.entry(root).or_insert_with(|| {
            let l = next_label;
            next_label += 1;
            l
        });
        result_labels.push(lbl);
    }
    result_labels
}

/// Euclidean distance between two points (clustering utility).
fn euclidean_dist_clustering(a: &[f64], b: &[f64]) -> f64 {
    a.iter()
        .zip(b.iter())
        .map(|(x, y)| (x - y).powi(2))
        .sum::<f64>()
        .sqrt()
}

/// Silhouette score for a clustering.
fn mlc_silhouette_score(data: &[Vec<f64>], labels: &[i64]) -> f64 {
    let n = data.len().min(labels.len());
    if n < 2 {
        return 0.0;
    }
    let mut total = 0.0f64;
    for i in 0..n {
        let ci = labels[i];
        let same: Vec<usize> = (0..n).filter(|&j| j != i && labels[j] == ci).collect();
        if same.is_empty() {
            continue;
        }
        let a_i = same
            .iter()
            .map(|&j| euclidean_dist_clustering(&data[i], &data[j]))
            .sum::<f64>()
            / same.len() as f64;
        let mut cluster_ids: Vec<i64> = labels[..n].iter().cloned().collect();
        cluster_ids.sort_unstable();
        cluster_ids.dedup();
        let b_i = cluster_ids
            .iter()
            .filter(|&&c| c != ci)
            .map(|&c| {
                let other: Vec<usize> = (0..n).filter(|&j| labels[j] == c).collect();
                if other.is_empty() {
                    f64::INFINITY
                } else {
                    other
                        .iter()
                        .map(|&j| euclidean_dist_clustering(&data[i], &data[j]))
                        .sum::<f64>()
                        / other.len() as f64
                }
            })
            .fold(f64::INFINITY, f64::min);
        let s_i = if b_i.is_infinite() {
            0.0
        } else {
            (b_i - a_i) / a_i.max(b_i)
        };
        total += s_i;
    }
    total / n as f64
}

/// Davies-Bouldin index.
fn mlc_davies_bouldin(data: &[Vec<f64>], labels: &[i64]) -> f64 {
    let n = data.len().min(labels.len());
    if n < 2 {
        return 0.0;
    }
    let mut cluster_ids: Vec<i64> = labels[..n].iter().cloned().collect();
    cluster_ids.sort_unstable();
    cluster_ids.dedup();
    let k = cluster_ids.len();
    if k < 2 {
        return 0.0;
    }
    let dim = if data.is_empty() {
        return 0.0;
    } else {
        data[0].len()
    };
    let centroids: Vec<Vec<f64>> = cluster_ids
        .iter()
        .map(|&c| {
            let pts: Vec<&Vec<f64>> = (0..n)
                .filter(|&i| labels[i] == c)
                .map(|i| &data[i])
                .collect();
            if pts.is_empty() {
                return vec![0.0; dim];
            }
            (0..dim)
                .map(|d| pts.iter().map(|p| p[d]).sum::<f64>() / pts.len() as f64)
                .collect()
        })
        .collect();
    let scatter: Vec<f64> = cluster_ids
        .iter()
        .enumerate()
        .map(|(ci, &c)| {
            let pts: Vec<&Vec<f64>> = (0..n)
                .filter(|&i| labels[i] == c)
                .map(|i| &data[i])
                .collect();
            if pts.is_empty() {
                return 0.0;
            }
            pts.iter()
                .map(|p| euclidean_dist_clustering(p, &centroids[ci]))
                .sum::<f64>()
                / pts.len() as f64
        })
        .collect();
    (0..k)
        .map(|i| {
            (0..k)
                .filter(|&j| j != i)
                .map(|j| {
                    let d = euclidean_dist_clustering(&centroids[i], &centroids[j]);
                    if d < 1e-12 {
                        0.0
                    } else {
                        (scatter[i] + scatter[j]) / d
                    }
                })
                .fold(0.0_f64, f64::max)
        })
        .sum::<f64>()
        / k as f64
}

/// Calinski-Harabasz score.
fn mlc_calinski_harabasz(data: &[Vec<f64>], labels: &[i64]) -> f64 {
    let n = data.len().min(labels.len());
    if n < 2 {
        return 0.0;
    }
    if data.is_empty() {
        return 0.0;
    }
    let dim = data[0].len();
    let mut cluster_ids: Vec<i64> = labels[..n].iter().cloned().collect();
    cluster_ids.sort_unstable();
    cluster_ids.dedup();
    let k = cluster_ids.len();
    if k < 2 || k >= n {
        return 0.0;
    }
    let global_mean: Vec<f64> = (0..dim)
        .map(|d| data[..n].iter().map(|r| r[d]).sum::<f64>() / n as f64)
        .collect();
    let mut bss = 0.0f64;
    let mut wss = 0.0f64;
    for &c in &cluster_ids {
        let pts: Vec<&Vec<f64>> = (0..n)
            .filter(|&i| labels[i] == c)
            .map(|i| &data[i])
            .collect();
        let nc = pts.len() as f64;
        if pts.is_empty() {
            continue;
        }
        let centroid: Vec<f64> = (0..dim)
            .map(|d| pts.iter().map(|p| p[d]).sum::<f64>() / nc)
            .collect();
        bss += nc * euclidean_dist_clustering(&centroid, &global_mean).powi(2);
        wss += pts
            .iter()
            .map(|p| euclidean_dist_clustering(p, &centroid).powi(2))
            .sum::<f64>();
    }
    if wss < 1e-12 {
        return 0.0;
    }
    (bss / (k as f64 - 1.0)) / (wss / (n as f64 - k as f64))
}

/// Adjusted Rand Index.
fn mlc_adjusted_rand_index(true_labels: &[i64], pred_labels: &[i64]) -> f64 {
    let n = true_labels.len().min(pred_labels.len());
    if n == 0 {
        return 0.0;
    }
    let mut contingency: HashMap<(i64, i64), usize> = HashMap::new();
    for i in 0..n {
        *contingency
            .entry((true_labels[i], pred_labels[i]))
            .or_insert(0) += 1;
    }
    let mut row_sums: HashMap<i64, usize> = HashMap::new();
    let mut col_sums: HashMap<i64, usize> = HashMap::new();
    for (&(r, c), &v) in &contingency {
        *row_sums.entry(r).or_insert(0) += v;
        *col_sums.entry(c).or_insert(0) += v;
    }
    let comb2 = |x: usize| -> f64 {
        if x < 2 {
            0.0
        } else {
            (x * (x - 1)) as f64 / 2.0
        }
    };
    let sum_cij: f64 = contingency.values().map(|&v| comb2(v)).sum();
    let sum_ai: f64 = row_sums.values().map(|&v| comb2(v)).sum();
    let sum_bj: f64 = col_sums.values().map(|&v| comb2(v)).sum();
    let cn2 = comb2(n);
    let expected = sum_ai * sum_bj / cn2.max(1.0);
    let max_term = (sum_ai + sum_bj) / 2.0;
    let denom = max_term - expected;
    if denom.abs() < 1e-12 {
        return 1.0;
    }
    (sum_cij - expected) / denom
}

/// Mutual information score.
fn mlc_mutual_info_score(true_labels: &[i64], pred_labels: &[i64]) -> f64 {
    let n = true_labels.len().min(pred_labels.len());
    if n == 0 {
        return 0.0;
    }
    let nf = n as f64;
    let mut joint: HashMap<(i64, i64), usize> = HashMap::new();
    for i in 0..n {
        *joint.entry((true_labels[i], pred_labels[i])).or_insert(0) += 1;
    }
    let mut p_x: HashMap<i64, f64> = HashMap::new();
    let mut p_y: HashMap<i64, f64> = HashMap::new();
    for (&(x, y), &c) in &joint {
        *p_x.entry(x).or_insert(0.0) += c as f64 / nf;
        *p_y.entry(y).or_insert(0.0) += c as f64 / nf;
    }
    joint
        .iter()
        .map(|(&(x, y), &c)| {
            let pxy = c as f64 / nf;
            let px = p_x[&x];
            let py = p_y[&y];
            if pxy > 1e-12 && px > 1e-12 && py > 1e-12 {
                pxy * (pxy / (px * py)).ln()
            } else {
                0.0
            }
        })
        .sum()
}

/// Simplified PCA variance ratio from column variances (approximation).
fn mlc_pca_variance_ratio(data: &[Vec<f64>]) -> Vec<f64> {
    if data.is_empty() {
        return vec![];
    }
    let dim = data[0].len();
    let n = data.len() as f64;
    let variances: Vec<f64> = (0..dim)
        .map(|d| {
            let mean = data
                .iter()
                .map(|r| if d < r.len() { r[d] } else { 0.0 })
                .sum::<f64>()
                / n;
            data.iter()
                .map(|r| {
                    let v = if d < r.len() { r[d] } else { 0.0 };
                    (v - mean).powi(2)
                })
                .sum::<f64>()
                / n
        })
        .collect();
    let total: f64 = variances.iter().sum();
    if total < 1e-12 {
        return vec![1.0 / dim as f64; dim];
    }
    variances.iter().map(|&v| v / total).collect()
}

/// Z-score standardize each column of the data matrix.
fn mlc_standardize(data: &[Vec<f64>]) -> Vec<Vec<f64>> {
    if data.is_empty() {
        return vec![];
    }
    let dim = data[0].len();
    let n = data.len() as f64;
    let means: Vec<f64> = (0..dim)
        .map(|d| data.iter().map(|r| r[d]).sum::<f64>() / n)
        .collect();
    let stds: Vec<f64> = (0..dim)
        .map(|d| {
            let m = means[d];
            let var = data.iter().map(|r| (r[d] - m).powi(2)).sum::<f64>() / n;
            var.sqrt().max(1e-12)
        })
        .collect();
    data.iter()
        .map(|row| (0..dim).map(|d| (row[d] - means[d]) / stds[d]).collect())
        .collect()
}

/// Min-max normalize each column of the data matrix to [0, 1].
fn mlc_minmax_normalize(data: &[Vec<f64>]) -> Vec<Vec<f64>> {
    if data.is_empty() {
        return vec![];
    }
    let dim = data[0].len();
    let mins: Vec<f64> = (0..dim)
        .map(|d| data.iter().map(|r| r[d]).fold(f64::INFINITY, f64::min))
        .collect();
    let maxs: Vec<f64> = (0..dim)
        .map(|d| data.iter().map(|r| r[d]).fold(f64::NEG_INFINITY, f64::max))
        .collect();
    data.iter()
        .map(|row| {
            (0..dim)
                .map(|d| {
                    let range = maxs[d] - mins[d];
                    if range < 1e-12 {
                        0.0
                    } else {
                        (row[d] - mins[d]) / range
                    }
                })
                .collect()
        })
        .collect()
}

/// Compute n_features x n_features covariance matrix.
fn mlc_covariance_matrix(data: &[Vec<f64>]) -> Vec<Vec<f64>> {
    if data.is_empty() {
        return vec![];
    }
    let dim = data[0].len();
    let n = data.len() as f64;
    let means: Vec<f64> = (0..dim)
        .map(|d| data.iter().map(|r| r[d]).sum::<f64>() / n)
        .collect();
    (0..dim)
        .map(|i| {
            (0..dim)
                .map(|j| {
                    data.iter()
                        .map(|r| (r[i] - means[i]) * (r[j] - means[j]))
                        .sum::<f64>()
                        / n
                })
                .collect()
        })
        .collect()
}

/// Compute n_features x n_features Pearson correlation matrix.
fn mlc_correlation_matrix(data: &[Vec<f64>]) -> Vec<Vec<f64>> {
    if data.is_empty() {
        return vec![];
    }
    let cov = mlc_covariance_matrix(data);
    let dim = cov.len();
    let stds: Vec<f64> = (0..dim).map(|i| cov[i][i].sqrt().max(1e-12)).collect();
    (0..dim)
        .map(|i| (0..dim).map(|j| cov[i][j] / (stds[i] * stds[j])).collect())
        .collect()
}

// ── Graph flow & connectivity private helpers ────────────────────────────────

/// Build an unweighted adjacency list from a PQL Object graph representation.
fn gflow_build_unweighted_adj(
    graph_obj: &std::collections::HashMap<String, Value>,
    idx: &std::collections::HashMap<String, usize>,
    n: usize,
) -> Vec<Vec<usize>> {
    let mut adj: Vec<Vec<usize>> = vec![vec![]; n];
    for (u, neighbors) in graph_obj {
        if let Some(&ui) = idx.get(u) {
            if let Value::Array(arr) = neighbors {
                for item in arr {
                    match item {
                        Value::Array(edge) if !edge.is_empty() => {
                            let v = match &edge[0] {
                                Value::String(s) => s.clone(),
                                _ => continue,
                            };
                            if let Some(&vi) = idx.get(&v) {
                                if !adj[ui].contains(&vi) {
                                    adj[ui].push(vi);
                                }
                            }
                        }
                        Value::String(v) => {
                            if let Some(&vi) = idx.get(v) {
                                if !adj[ui].contains(&vi) {
                                    adj[ui].push(vi);
                                }
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
    }
    adj
}

/// BFS distances from source; unreachable nodes get usize::MAX.
fn gflow_bfs_distances(adj: &[Vec<usize>], src: usize, n: usize) -> Vec<usize> {
    let mut dist = vec![usize::MAX; n];
    dist[src] = 0;
    let mut queue = std::collections::VecDeque::new();
    queue.push_back(src);
    while let Some(u) = queue.pop_front() {
        for &v in &adj[u] {
            if dist[v] == usize::MAX {
                dist[v] = dist[u] + 1;
                queue.push_back(v);
            }
        }
    }
    dist
}

/// O(n^2) Dijkstra; returns distance vector (INFINITY = unreachable).
fn gflow_dijkstra(adj: &[Vec<(usize, f64)>], src: usize, n: usize) -> Vec<f64> {
    let mut dist = vec![f64::INFINITY; n];
    let mut visited = vec![false; n];
    dist[src] = 0.0;
    for _ in 0..n {
        let u = (0..n).filter(|&i| !visited[i]).min_by(|&a, &b| {
            dist[a]
                .partial_cmp(&dist[b])
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        let u = match u {
            Some(u) => u,
            None => break,
        };
        if dist[u] == f64::INFINITY {
            break;
        }
        visited[u] = true;
        for &(v, w) in &adj[u] {
            let nd = dist[u] + w;
            if nd < dist[v] {
                dist[v] = nd;
            }
        }
    }
    dist
}

/// Dijkstra + path reconstruction from source to target.
fn gflow_dijkstra_path(adj: &[Vec<(usize, f64)>], src: usize, tgt: usize, n: usize) -> Vec<usize> {
    let mut dist = vec![f64::INFINITY; n];
    let mut prev = vec![usize::MAX; n];
    let mut visited = vec![false; n];
    dist[src] = 0.0;
    for _ in 0..n {
        let u = (0..n).filter(|&i| !visited[i]).min_by(|&a, &b| {
            dist[a]
                .partial_cmp(&dist[b])
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        let u = match u {
            Some(u) => u,
            None => break,
        };
        if dist[u] == f64::INFINITY {
            break;
        }
        visited[u] = true;
        for &(v, w) in &adj[u] {
            let nd = dist[u] + w;
            if nd < dist[v] {
                dist[v] = nd;
                prev[v] = u;
            }
        }
    }
    if dist[tgt] == f64::INFINITY {
        return vec![];
    }
    let mut path = vec![];
    let mut cur = tgt;
    loop {
        path.push(cur);
        if cur == src {
            break;
        }
        let p = prev[cur];
        if p == usize::MAX {
            return vec![];
        }
        cur = p;
    }
    path.reverse();
    path
}

/// Edmonds-Karp (BFS-based Ford-Fulkerson) maximum flow.
fn gflow_edmonds_karp(cap: &mut Vec<Vec<f64>>, src: usize, snk: usize, n: usize) -> f64 {
    let mut total_flow = 0.0f64;
    loop {
        let mut parent = vec![usize::MAX; n];
        let mut visited = vec![false; n];
        let mut queue = std::collections::VecDeque::new();
        queue.push_back(src);
        visited[src] = true;
        while let Some(u) = queue.pop_front() {
            if u == snk {
                break;
            }
            for v in 0..n {
                if !visited[v] && cap[u][v] > 1e-9 {
                    visited[v] = true;
                    parent[v] = u;
                    queue.push_back(v);
                }
            }
        }
        if !visited[snk] {
            break;
        }
        let mut flow = f64::INFINITY;
        let mut cur = snk;
        while cur != src {
            let p = parent[cur];
            if cap[p][cur] < flow {
                flow = cap[p][cur];
            }
            cur = p;
        }
        let mut cur = snk;
        while cur != src {
            let p = parent[cur];
            cap[p][cur] -= flow;
            cap[cur][p] += flow;
            cur = p;
        }
        total_flow += flow;
    }
    total_flow
}

/// DFS finishing order (post-order) for Kosaraju's SCC / topological sort.
fn gflow_dfs_finish(
    adj: &[Vec<usize>],
    start: usize,
    visited: &mut Vec<bool>,
    order: &mut Vec<usize>,
) {
    let mut stack: Vec<(usize, usize)> = vec![(start, 0)];
    visited[start] = true;
    while let Some((u, ni)) = stack.last_mut() {
        let u = *u;
        if *ni < adj[u].len() {
            let v = adj[u][*ni];
            *ni += 1;
            if !visited[v] {
                visited[v] = true;
                stack.push((v, 0));
            }
        } else {
            order.push(u);
            stack.pop();
        }
    }
}

/// DFS-based directed cycle detection using 3-color marking.
fn gflow_dfs_cycle(adj: &[Vec<usize>], start: usize, color: &mut Vec<u8>, has_cycle: &mut bool) {
    let mut stack: Vec<(usize, usize)> = vec![(start, 0)];
    color[start] = 1;
    while let Some((u, ni)) = stack.last_mut() {
        let u = *u;
        if *ni < adj[u].len() {
            let v = adj[u][*ni];
            *ni += 1;
            if color[v] == 1 {
                *has_cycle = true;
                return;
            }
            if color[v] == 0 {
                color[v] = 1;
                stack.push((v, 0));
            }
        } else {
            color[u] = 2;
            stack.pop();
        }
    }
}

/// Tarjan-style articulation points (iterative DFS).
fn gflow_articulation_points(adj: &[Vec<usize>], n: usize) -> Vec<usize> {
    let mut disc = vec![usize::MAX; n];
    let mut low = vec![0usize; n];
    let mut parent = vec![usize::MAX; n];
    let mut timer = 0usize;
    let mut ap = std::collections::HashSet::new();

    for start in 0..n {
        if disc[start] != usize::MAX {
            continue;
        }
        let mut stack: Vec<(usize, usize)> = vec![(start, 0)];
        disc[start] = timer;
        low[start] = timer;
        timer += 1;
        while let Some((u, ni)) = stack.last_mut() {
            let u = *u;
            if *ni < adj[u].len() {
                let v = adj[u][*ni];
                *ni += 1;
                if disc[v] == usize::MAX {
                    parent[v] = u;
                    disc[v] = timer;
                    low[v] = timer;
                    timer += 1;
                    stack.push((v, 0));
                } else if v != parent[u] {
                    if disc[v] < low[u] {
                        low[u] = disc[v];
                    }
                }
            } else {
                stack.pop();
                if let Some(&(p, _)) = stack.last() {
                    if low[u] < low[p] {
                        low[p] = low[u];
                    }
                    if parent[p] == usize::MAX {
                        let children = adj[p].iter().filter(|&&c| parent[c] == p).count();
                        if children > 1 {
                            ap.insert(p);
                        }
                    } else if low[u] >= disc[p] {
                        ap.insert(p);
                    }
                }
            }
        }
    }
    ap.into_iter().collect()
}

/// Tarjan-style bridge detection (iterative DFS).
fn gflow_bridge_edges(adj: &[Vec<usize>], n: usize) -> Vec<(usize, usize)> {
    let mut disc = vec![usize::MAX; n];
    let mut low = vec![0usize; n];
    let mut parent = vec![usize::MAX; n];
    let mut timer = 0usize;
    let mut bridges: Vec<(usize, usize)> = vec![];

    for start in 0..n {
        if disc[start] != usize::MAX {
            continue;
        }
        let mut stack: Vec<(usize, usize)> = vec![(start, 0)];
        disc[start] = timer;
        low[start] = timer;
        timer += 1;
        while let Some((u, ni)) = stack.last_mut() {
            let u = *u;
            if *ni < adj[u].len() {
                let v = adj[u][*ni];
                *ni += 1;
                if disc[v] == usize::MAX {
                    parent[v] = u;
                    disc[v] = timer;
                    low[v] = timer;
                    timer += 1;
                    stack.push((v, 0));
                } else if v != parent[u] {
                    if disc[v] < low[u] {
                        low[u] = disc[v];
                    }
                }
            } else {
                stack.pop();
                if let Some(&(p, _)) = stack.last() {
                    if low[u] < low[p] {
                        low[p] = low[u];
                    }
                    if low[u] > disc[p] {
                        bridges.push((p.min(u), p.max(u)));
                    }
                }
            }
        }
    }
    bridges
}

/// Gaussian elimination determinant for small square matrices.
fn gflow_determinant(mat: &mut Vec<Vec<f64>>, m: usize) -> f64 {
    if m == 0 {
        return 1.0;
    }
    let mut det = 1.0f64;
    for col in 0..m {
        let pivot = (col..m).max_by(|&a, &b| {
            mat[a][col]
                .abs()
                .partial_cmp(&mat[b][col].abs())
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        let pivot = match pivot {
            Some(p) => p,
            None => return 0.0,
        };
        if mat[pivot][col].abs() < 1e-12 {
            return 0.0;
        }
        if pivot != col {
            mat.swap(col, pivot);
            det = -det;
        }
        det *= mat[col][col];
        let div = mat[col][col];
        for row in (col + 1)..m {
            let factor = mat[row][col] / div;
            for c in col..m {
                mat[row][c] -= factor * mat[col][c];
            }
        }
    }
    det
}

/// BFS reachable set from a node in an unweighted string adjacency map.
#[allow(dead_code)]
fn gflow_bfs_reachable(
    adj: &std::collections::HashMap<String, Vec<String>>,
    src: &str,
) -> std::collections::HashSet<String> {
    let mut visited = std::collections::HashSet::new();
    let mut queue = std::collections::VecDeque::new();
    if adj.contains_key(src) {
        queue.push_back(src.to_string());
        visited.insert(src.to_string());
    }
    while let Some(node) = queue.pop_front() {
        if let Some(neighbors) = adj.get(&node) {
            for n in neighbors {
                if visited.insert(n.clone()) {
                    queue.push_back(n.clone());
                }
            }
        }
    }
    visited
}

// ── Encoding private helpers (enc_ prefix) ───────────────────────────────────

/// Encode bytes as URL-safe base64 (no padding).
fn enc_base64_url_encode(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    let mut out = String::new();
    let mut i = 0;
    while i < data.len() {
        let b0 = data[i] as u32;
        let b1 = if i + 1 < data.len() {
            data[i + 1] as u32
        } else {
            0
        };
        let b2 = if i + 2 < data.len() {
            data[i + 2] as u32
        } else {
            0
        };
        out.push(CHARS[((b0 >> 2) & 0x3f) as usize] as char);
        out.push(CHARS[(((b0 << 4) | (b1 >> 4)) & 0x3f) as usize] as char);
        if i + 1 < data.len() {
            out.push(CHARS[(((b1 << 2) | (b2 >> 6)) & 0x3f) as usize] as char);
        }
        if i + 2 < data.len() {
            out.push(CHARS[(b2 & 0x3f) as usize] as char);
        }
        i += 3;
    }
    out
}

/// Decode URL-safe base64 (no padding required).
fn enc_base64_url_decode(s: &str) -> Option<Vec<u8>> {
    fn char_val(c: u8) -> Option<u8> {
        match c {
            b'A'..=b'Z' => Some(c - b'A'),
            b'a'..=b'z' => Some(c - b'a' + 26),
            b'0'..=b'9' => Some(c - b'0' + 52),
            b'-' => Some(62),
            b'_' => Some(63),
            b'=' => Some(0),
            _ => None,
        }
    }
    let filtered: Vec<u8> = s.bytes().filter(|&b| b != b'\n' && b != b'\r').collect();
    // Pad to multiple of 4
    let padded_len = (filtered.len() + 3) / 4 * 4;
    let mut padded = filtered.clone();
    while padded.len() < padded_len {
        padded.push(b'=');
    }
    if padded.len() % 4 != 0 {
        return None;
    }
    let mut result = Vec::new();
    let mut i = 0;
    while i < padded.len() {
        let c0 = char_val(padded[i])?;
        let c1 = char_val(padded[i + 1])?;
        let c2 = char_val(padded[i + 2])?;
        let c3 = char_val(padded[i + 3])?;
        result.push((c0 << 2) | (c1 >> 4));
        if padded[i + 2] != b'=' {
            result.push(((c1 & 0xf) << 4) | (c2 >> 2));
        }
        if padded[i + 3] != b'=' {
            result.push(((c2 & 0x3) << 6) | c3);
        }
        i += 4;
    }
    Some(result)
}

/// Encode bytes as base32 (RFC 4648, A-Z2-7 with = padding).
fn enc_base32_encode(data: &[u8]) -> String {
    const ALPHABET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
    let mut out = String::new();
    let mut buf: u64 = 0;
    let mut bits: u32 = 0;
    for &byte in data {
        buf = (buf << 8) | byte as u64;
        bits += 8;
        while bits >= 5 {
            bits -= 5;
            out.push(ALPHABET[((buf >> bits) & 0x1f) as usize] as char);
        }
    }
    if bits > 0 {
        buf <<= 5 - bits;
        out.push(ALPHABET[(buf & 0x1f) as usize] as char);
    }
    // Pad to multiple of 8
    while out.len() % 8 != 0 {
        out.push('=');
    }
    out
}

/// Decode base32 string.
fn enc_base32_decode(s: &str) -> Option<Vec<u8>> {
    fn char_val(c: u8) -> Option<u8> {
        match c {
            b'A'..=b'Z' => Some(c - b'A'),
            b'a'..=b'z' => Some(c - b'a'),
            b'2'..=b'7' => Some(c - b'2' + 26),
            _ => None,
        }
    }
    let mut buf: u64 = 0;
    let mut bits: u32 = 0;
    let mut result = Vec::new();
    for byte in s.bytes() {
        if byte == b'=' {
            break;
        }
        let v = char_val(byte)?;
        buf = (buf << 5) | v as u64;
        bits += 5;
        if bits >= 8 {
            bits -= 8;
            result.push(((buf >> bits) & 0xff) as u8);
        }
    }
    Some(result)
}

/// Encode bytes as Bitcoin base58.
fn enc_base58_encode(data: &[u8]) -> String {
    const ALPHABET: &[u8] = b"123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
    if data.is_empty() {
        return String::new();
    }
    let mut num: Vec<u8> = data.to_vec();
    let mut result = Vec::new();
    let leading_zeros = num.iter().take_while(|&&b| b == 0).count();
    while !num.is_empty() && !(num.len() == 1 && num[0] == 0) {
        let mut remainder = 0u16;
        let mut new_num = Vec::new();
        for &byte in &num {
            let cur = remainder * 256 + byte as u16;
            let q = cur / 58;
            remainder = cur % 58;
            if !new_num.is_empty() || q > 0 {
                new_num.push(q as u8);
            }
        }
        result.push(ALPHABET[remainder as usize]);
        num = new_num;
    }
    for _ in 0..leading_zeros {
        result.push(b'1');
    }
    result.reverse();
    String::from_utf8(result).unwrap_or_default()
}

/// Decode Bitcoin base58.
fn enc_base58_decode(s: &str) -> Option<Vec<u8>> {
    const ALPHABET: &[u8] = b"123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
    let leading_ones = s.bytes().take_while(|&b| b == b'1').count();
    let mut num: Vec<u8> = vec![0];
    for byte in s.bytes() {
        let digit = ALPHABET.iter().position(|&c| c == byte)? as u16;
        let mut carry = digit;
        for n in num.iter_mut().rev() {
            let cur = *n as u16 * 58 + carry;
            *n = (cur & 0xff) as u8;
            carry = cur >> 8;
        }
        while carry > 0 {
            num.insert(0, (carry & 0xff) as u8);
            carry >>= 8;
        }
    }
    let skip = num.iter().take_while(|&&b| b == 0).count();
    let mut result = vec![0u8; leading_ones];
    result.extend_from_slice(&num[skip..]);
    Some(result)
}

