/// Parse a chemical formula string like "H2O", "C6H12O6", "NaCl".
/// Returns a HashMap of symbol -> count, or None if invalid.
fn chem_parse_formula(formula: &str) -> Option<std::collections::HashMap<String, usize>> {
    let mut map: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    let chars: Vec<char> = formula.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i].is_ascii_uppercase() {
            let mut sym = String::new();
            sym.push(chars[i]);
            i += 1;
            while i < chars.len() && chars[i].is_ascii_lowercase() {
                sym.push(chars[i]);
                i += 1;
            }
            // Validate symbol has known mass (nonzero)
            if chem_atomic_mass_by_symbol(&sym) == 0.0 {
                return None;
            }
            let mut count_str = String::new();
            while i < chars.len() && chars[i].is_ascii_digit() {
                count_str.push(chars[i]);
                i += 1;
            }
            let count: usize = if count_str.is_empty() {
                1
            } else {
                count_str.parse().ok()?
            };
            if count == 0 {
                return None;
            }
            *map.entry(sym).or_insert(0) += count;
        } else {
            return None;
        }
    }
    if map.is_empty() {
        None
    } else {
        Some(map)
    }
}

/// Greatest common divisor helper for empirical formula reduction.
fn chem_gcd(a: usize, b: usize) -> usize {
    if b == 0 {
        a
    } else {
        chem_gcd(b, a % b)
    }
}

// ── Information theory private helpers ───────────────────────────────────────

/// Normalize a slice so it sums to 1.0. Handles frequency arrays automatically.
fn info_normalize(arr: &[f64]) -> Vec<f64> {
    let total: f64 = arr.iter().filter(|&&x| x > 0.0).sum();
    if total == 0.0 {
        return vec![0.0; arr.len()];
    }
    arr.iter().map(|&x| x.max(0.0) / total).collect()
}

/// Shannon entropy in bits H = -sum(p * log2(p)).
/// Accepts either probability arrays (sum ~1) or frequency/count arrays
/// (normalizes first).
fn info_shannon_entropy_bits(arr: &[f64]) -> f64 {
    let norm = info_normalize(arr);
    norm.iter()
        .filter(|&&p| p > 0.0)
        .map(|&p| -p * p.log2())
        .sum()
}

/// Binary entropy function H(p) = -p*log2(p) - (1-p)*log2(1-p).
fn info_binary_entropy(p: f64) -> f64 {
    let p = p.max(0.0).min(1.0);
    if p == 0.0 || p == 1.0 {
        return 0.0;
    }
    -p * p.log2() - (1.0 - p) * (1.0 - p).log2()
}

/// Extract a Vec<Vec<f64>> matrix from a Value::Array of Value::Array.
fn info_extract_matrix(v: Value) -> Vec<Vec<f64>> {
    match v {
        Value::Array(outer) => outer
            .iter()
            .map(|row| match row {
                Value::Array(inner) => inner
                    .iter()
                    .map(|x| match x {
                        Value::Float(f) => *f,
                        Value::Integer(i) => *i as f64,
                        _ => 0.0,
                    })
                    .collect(),
                Value::Float(f) => vec![*f],
                Value::Integer(i) => vec![*i as f64],
                _ => vec![],
            })
            .collect(),
        _ => vec![],
    }
}

/// LZ76 complexity: number of distinct phrases in Lempel-Ziv 1976 parsing.
fn info_lz76_complexity_str(s: &str) -> usize {
    if s.is_empty() {
        return 0;
    }
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut complexity = 0usize;
    let mut i = 0usize;
    while i < n {
        let mut l = 1usize;
        let mut found = true;
        while found && i + l <= n {
            let phrase: String = chars[i..i + l].iter().collect();
            let history: String = chars[..i + l - 1].iter().collect();
            found = history.contains(&phrase[..]);
            if found {
                l += 1;
            }
        }
        complexity += 1;
        i += l;
    }
    complexity
}

/// Run-length encoding output length (number of (count, value) pairs * 2).
fn info_rle_length(data: &[u8]) -> usize {
    if data.is_empty() {
        return 0;
    }
    let mut count = 0usize;
    let mut i = 0usize;
    while i < data.len() {
        let mut j = i + 1;
        while j < data.len() && data[j] == data[i] {
            j += 1;
        }
        count += 1;
        i = j;
    }
    count * 2
}

/// Population variance.
fn info_variance(data: &[f64]) -> f64 {
    let n = data.len();
    if n == 0 {
        return 0.0;
    }
    let mean = data.iter().sum::<f64>() / n as f64;
    data.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / n as f64
}

// ── Geospatial private helper functions ──────────────────────────────────────

/// Haversine distance between two lat/lon points in kilometers.
/// Earth radius = 6371.0 km.
fn geo_haversine_km(lat1: f64, lon1: f64, lat2: f64, lon2: f64) -> f64 {
    let r = 6371.0_f64;
    let dlat = (lat2 - lat1).to_radians();
    let dlon = (lon2 - lon1).to_radians();
    let a = (dlat / 2.0).sin().powi(2)
        + lat1.to_radians().cos() * lat2.to_radians().cos() * (dlon / 2.0).sin().powi(2);
    2.0 * r * a.sqrt().asin()
}

/// Encode (lat, lon) as a geohash string of the given precision (1..=12).
/// Uses the standard base32 alphabet "0123456789bcdefghjkmnpqrstuvwxyz".
fn geo_geohash_encode(lat: f64, lon: f64, precision: usize) -> String {
    const BASE32: &[u8] = b"0123456789bcdefghjkmnpqrstuvwxyz";
    let mut min_lat = -90.0_f64;
    let mut max_lat = 90.0_f64;
    let mut min_lon = -180.0_f64;
    let mut max_lon = 180.0_f64;
    let mut hash = String::new();
    let mut bits = 0_usize;
    let mut code = 0_usize;
    let mut is_lon = true;
    while hash.len() < precision {
        if is_lon {
            let mid = (min_lon + max_lon) / 2.0;
            if lon >= mid {
                code = (code << 1) | 1;
                min_lon = mid;
            } else {
                code <<= 1;
                max_lon = mid;
            }
        } else {
            let mid = (min_lat + max_lat) / 2.0;
            if lat >= mid {
                code = (code << 1) | 1;
                min_lat = mid;
            } else {
                code <<= 1;
                max_lat = mid;
            }
        }
        is_lon = !is_lon;
        bits += 1;
        if bits == 5 {
            hash.push(BASE32[code] as char);
            bits = 0;
            code = 0;
        }
    }
    hash
}

/// Decode a geohash string to (lat, lon, lat_err, lon_err).
/// Returns the center point plus the half-error in each dimension.
fn geo_geohash_decode(hash: &str) -> (f64, f64, f64, f64) {
    const BASE32: &[u8] = b"0123456789bcdefghjkmnpqrstuvwxyz";
    let mut min_lat = -90.0_f64;
    let mut max_lat = 90.0_f64;
    let mut min_lon = -180.0_f64;
    let mut max_lon = 180.0_f64;
    let mut is_lon = true;
    for ch in hash.chars() {
        let idx = BASE32.iter().position(|&b| b == ch as u8).unwrap_or(0);
        for bit in (0..5).rev() {
            let bit_set = (idx >> bit) & 1 == 1;
            if is_lon {
                let mid = (min_lon + max_lon) / 2.0;
                if bit_set {
                    min_lon = mid;
                } else {
                    max_lon = mid;
                }
            } else {
                let mid = (min_lat + max_lat) / 2.0;
                if bit_set {
                    min_lat = mid;
                } else {
                    max_lat = mid;
                }
            }
            is_lon = !is_lon;
        }
    }
    let lat = (min_lat + max_lat) / 2.0;
    let lon = (min_lon + max_lon) / 2.0;
    let lat_err = (max_lat - min_lat) / 2.0;
    let lon_err = (max_lon - min_lon) / 2.0;
    (lat, lon, lat_err, lon_err)
}

/// Convert a Value to a Vec<f64>. Arrays of numbers are converted element-by-element.
/// Scalar numbers are wrapped in a 1-element vec. Other values produce empty vec.
fn value_to_f64_vec_from_val(v: Value) -> Vec<f64> {
    match v {
        Value::Array(arr) => arr
            .into_iter()
            .map(|x| match x {
                Value::Float(f) => f,
                Value::Integer(i) => i as f64,
                Value::Bool(b) => {
                    if b {
                        1.0
                    } else {
                        0.0
                    }
                }
                _ => 0.0,
            })
            .collect(),
        Value::Float(f) => vec![f],
        Value::Integer(i) => vec![i as f64],
        _ => vec![],
    }
}

// ── Graph centrality helper parsers ──────────────────────────────────────────

fn parse_pagerank_args(
    executor: &super::Executor,
    args: &[crate::pql::ast::Expression],
    row: &super::Row,
) -> crate::error::Result<(Option<String>, usize, f64)> {
    let edge_type = if !args.is_empty() {
        match evaluate_expression(executor, &args[0], row)? {
            Value::String(s) if !s.is_empty() => Some(s),
            _ => None,
        }
    } else {
        None
    };
    let iterations = if args.len() > 1 {
        match evaluate_expression(executor, &args[1], row)? {
            Value::Integer(i) => i.max(1) as usize,
            _ => 20,
        }
    } else {
        20
    };
    let damping = if args.len() > 2 {
        match evaluate_expression(executor, &args[2], row)? {
            Value::Float(f) => f.clamp(0.0, 1.0),
            Value::Integer(i) => (i as f64).clamp(0.0, 1.0),
            _ => 0.85,
        }
    } else {
        0.85
    };
    Ok((edge_type, iterations, damping))
}

fn parse_edge_type_arg(
    executor: &super::Executor,
    args: &[crate::pql::ast::Expression],
    row: &super::Row,
) -> crate::error::Result<Option<String>> {
    if args.is_empty() {
        return Ok(None);
    }
    match evaluate_expression(executor, &args[0], row)? {
        Value::String(s) if !s.is_empty() => Ok(Some(s)),
        _ => Ok(None),
    }
}

fn parse_edge_type_and_bool_arg(
    executor: &super::Executor,
    args: &[crate::pql::ast::Expression],
    row: &super::Row,
    default_bool: bool,
) -> crate::error::Result<(Option<String>, bool)> {
    let edge_type = if !args.is_empty() {
        match evaluate_expression(executor, &args[0], row)? {
            Value::String(s) if !s.is_empty() => Some(s),
            _ => None,
        }
    } else {
        None
    };
    let normalized = if args.len() > 1 {
        match evaluate_expression(executor, &args[1], row)? {
            Value::Bool(b) => b,
            _ => default_bool,
        }
    } else {
        default_bool
    };
    Ok((edge_type, normalized))
}

// ── Group-rows extraction helper ──────────────────────────────────────────────

/// Extracts the group rows from a grouped row (set during GROUP BY).
/// Returns Some(rows) if this row has a _group_rows key, None otherwise.
fn extract_group_rows(executor: &super::Executor, row: &super::Row) -> Option<Vec<super::Row>> {
    let _ = executor; // executor not needed currently but kept for API consistency
    let key = super::Executor::GROUP_ROWS_KEY;
    match row.data.get(key)? {
        super::Value::Array(arr) => {
            let rows: Vec<super::Row> = arr
                .iter()
                .filter_map(|v| {
                    if let super::Value::Object(map) = v {
                        Some(super::Row {
                            id: uuid::Uuid::nil(),
                            data: map.clone(),
                        })
                    } else {
                        None
                    }
                })
                .collect();
            if rows.is_empty() {
                None
            } else {
                Some(rows)
            }
        }
        _ => None,
    }
}

// ── Private validation helpers (val_ prefix) ──────────────────────────────────

/// Returns true if `s` is a valid date in "YYYY-MM-DD" format,
/// including leap-year and month-length checks.
fn val_is_valid_date_str(s: &str) -> bool {
    let parts: Vec<&str> = s.split('-').collect();
    if parts.len() != 3 {
        return false;
    }
    let y = match parts[0].parse::<i32>() {
        Ok(v) => v,
        Err(_) => return false,
    };
    let m = match parts[1].parse::<u32>() {
        Ok(v) => v,
        Err(_) => return false,
    };
    let d = match parts[2].parse::<u32>() {
        Ok(v) => v,
        Err(_) => return false,
    };
    if parts[0].len() != 4 || parts[1].len() != 2 || parts[2].len() != 2 {
        return false;
    }
    if m < 1 || m > 12 || d < 1 {
        return false;
    }
    let max_day = cal_days_in_month(y, m);
    if max_day == 0 {
        return false;
    }
    d <= max_day
}

/// Glob-style pattern matching: `*` matches any sequence of chars,
/// `?` matches exactly one char. Case-sensitive.
fn val_glob_match(s: &str, pattern: &str) -> bool {
    let sc: Vec<char> = s.chars().collect();
    let pc: Vec<char> = pattern.chars().collect();
    val_glob_recursive(&sc, &pc, 0, 0)
}

fn val_glob_recursive(s: &[char], p: &[char], si: usize, pi: usize) -> bool {
    if pi == p.len() {
        return si == s.len();
    }
    if p[pi] == '*' {
        let mut npi = pi + 1;
        while npi < p.len() && p[npi] == '*' {
            npi += 1;
        }
        for nsi in si..=s.len() {
            if val_glob_recursive(s, p, nsi, npi) {
                return true;
            }
        }
        return false;
    }
    if si == s.len() {
        return false;
    }
    if p[pi] == '?' || p[pi] == s[si] {
        return val_glob_recursive(s, p, si + 1, pi + 1);
    }
    false
}

/// Apply a named predicate to a single Value.
/// Supported predicates: "positive", "negative", "zero", "even", "odd", "nonempty", "null", "nonnull"
fn val_check_predicate(v: &Value, pred: &str) -> bool {
    match pred.to_lowercase().as_str() {
        "positive" | "pos" => match v {
            Value::Integer(i) => *i > 0,
            Value::Float(f) => *f > 0.0,
            _ => false,
        },
        "negative" | "neg" => match v {
            Value::Integer(i) => *i < 0,
            Value::Float(f) => *f < 0.0,
            _ => false,
        },
        "zero" => match v {
            Value::Integer(i) => *i == 0,
            Value::Float(f) => *f == 0.0,
            _ => false,
        },
        "even" => match v {
            Value::Integer(i) => *i % 2 == 0,
            Value::Float(f) if f.fract() == 0.0 => (*f as i64) % 2 == 0,
            _ => false,
        },
        "odd" => match v {
            Value::Integer(i) => *i % 2 != 0,
            Value::Float(f) if f.fract() == 0.0 => (*f as i64) % 2 != 0,
            _ => false,
        },
        "nonempty" | "non_empty" => match v {
            Value::Null => false,
            Value::String(s) => !s.is_empty(),
            Value::Array(a) => !a.is_empty(),
            _ => true,
        },
        "null" | "isnull" => matches!(v, Value::Null),
        "nonnull" | "not_null" => !matches!(v, Value::Null),
        _ => false,
    }
}

/// Safe cast: try to cast `v` to the type named by `type_str`.
/// Returns Null on failure.
fn val_cast_safe(v: Value, type_str: &str) -> Value {
    match type_str.to_lowercase().as_str() {
        "integer" | "int" => match v {
            Value::Integer(i) => Value::Integer(i),
            Value::Float(f) => Value::Integer(f as i64),
            Value::Bool(b) => Value::Integer(if b { 1 } else { 0 }),
            Value::String(s) => s
                .trim()
                .parse::<i64>()
                .map(Value::Integer)
                .unwrap_or(Value::Null),
            _ => Value::Null,
        },
        "float" | "double" => match v {
            Value::Integer(i) => Value::Float(i as f64),
            Value::Float(f) => Value::Float(f),
            Value::Bool(b) => Value::Float(if b { 1.0 } else { 0.0 }),
            Value::String(s) => s
                .trim()
                .parse::<f64>()
                .map(Value::Float)
                .unwrap_or(Value::Null),
            _ => Value::Null,
        },
        "string" | "text" | "str" => match v {
            Value::String(s) => Value::String(s),
            Value::Integer(i) => Value::String(i.to_string()),
            Value::Float(f) => Value::String(f.to_string()),
            Value::Bool(b) => Value::String(b.to_string()),
            Value::Null => Value::String("null".to_string()),
            _ => Value::Null,
        },
        "bool" | "boolean" => match v {
            Value::Bool(b) => Value::Bool(b),
            Value::Integer(i) => Value::Bool(i != 0),
            Value::Float(f) => Value::Bool(f != 0.0),
            Value::String(s) => match s.to_lowercase().as_str() {
                "true" | "1" | "yes" | "on" => Value::Bool(true),
                "false" | "0" | "no" | "off" => Value::Bool(false),
                _ => Value::Null,
            },
            _ => Value::Null,
        },
        _ => Value::Null,
    }
}

// ── Calendar private helpers (cal_ prefix) ────────────────────────────────────

fn cal_is_leap(year: i32) -> bool {
    (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)
}

fn cal_days_in_month(year: i32, month: u32) -> u32 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if cal_is_leap(year) {
                29
            } else {
                28
            }
        }
        _ => 0,
    }
}

/// Convert year/month/day to Julian Day Number (proleptic Gregorian).
fn cal_ymd_to_jdn(y: i32, m: u32, d: u32) -> i64 {
    let a = (14 - m as i32) / 12;
    let yr = y + 4800 - a;
    let mo = m as i32 + 12 * a - 3;
    d as i64 + ((153 * mo + 2) / 5) as i64 + 365 * yr as i64 + (yr / 4) as i64 - (yr / 100) as i64
        + (yr / 400) as i64
        - 32045
}

/// Convert Julian Day Number back to (year, month, day).
fn cal_jdn_to_ymd(jdn: i64) -> (i32, u32, u32) {
    let l = jdn + 68569;
    let n = (4 * l) / 146097;
    let l = l - (146097 * n + 3) / 4;
    let i = (4000 * (l + 1)) / 1461001;
    let l = l - (1461 * i) / 4 + 31;
    let j = (80 * l) / 2447;
    let d = l - (2447 * j) / 80;
    let l = j / 11;
    let m = j + 2 - 12 * l;
    let y = 100 * (n - 49) + i + l;
    (y as i32, m as u32, d as u32)
}

/// Day of week for a Julian Day Number. Returns 0=Sun,1=Mon,...,6=Sat.
fn cal_jdn_dow(jdn: i64) -> u32 {
    ((jdn + 1).rem_euclid(7)) as u32
}

/// Format year/month/day as "YYYY-MM-DD".
fn cal_format_ymd(y: i32, m: u32, d: u32) -> String {
    format!("{:04}-{:02}-{:02}", y, m, d)
}

/// Parse "YYYY-MM-DD" string. Returns Some((y, m, d)) or None.
fn cal_parse_ymd(s: &str) -> Option<(i32, u32, u32)> {
    let parts: Vec<&str> = s.split('-').collect();
    if parts.len() < 3 {
        return None;
    }
    let y = parts[0].parse::<i32>().ok()?;
    let m = parts[1].parse::<u32>().ok()?;
    let d = parts[2].parse::<u32>().ok()?;
    Some((y, m, d))
}

/// Convert Gregorian datetime to Unix timestamp (seconds since 1970-01-01 UTC).
fn gregorian_to_unix(year: i64, month: u32, day: u32, h: i64, min: i64, sec: i64) -> i64 {
    let jdn = cal_ymd_to_jdn(year as i32, month, day);
    let epoch_jdn = cal_ymd_to_jdn(1970, 1, 1);
    (jdn - epoch_jdn) * 86400 + h * 3600 + min * 60 + sec
}

/// Last day of month (u32). Returns 0 for invalid month.
fn last_day_of_month(year: i32, month: u32) -> u32 {
    cal_days_in_month(year, month)
}

/// Count business days (Mon-Fri) between two NaiveDate values.
fn business_days_between(start: chrono::NaiveDate, end: chrono::NaiveDate) -> i64 {
    use chrono::Datelike;
    let (s, e, sign) = if start <= end {
        (start, end, 1i64)
    } else {
        (end, start, -1i64)
    };
    let mut count: i64 = 0;
    let mut d = s;
    while d < e {
        let wd = d.weekday();
        use chrono::Weekday;
        if !matches!(wd, Weekday::Sat | Weekday::Sun) {
            count += 1;
        }
        d = d.succ_opt().unwrap_or(e);
    }
    sign * count
}

/// Parse a Value into chrono::NaiveDate (accepts "YYYY-MM-DD" strings or integer timestamps).
fn parse_date_from_value(v: &Value) -> Option<chrono::NaiveDate> {
    match v {
        Value::String(s) => {
            let s = s.trim();
            // Try "YYYY-MM-DD"
            if let Ok(d) = chrono::NaiveDate::parse_from_str(s, "%Y-%m-%d") {
                return Some(d);
            }
            // Try "YYYY-MM-DDTHH:MM:SS"
            if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S") {
                return Some(dt.date());
            }
            None
        }
        Value::Integer(ts) => {
            use chrono::TimeZone;
            chrono::Utc
                .timestamp_opt(*ts, 0)
                .single()
                .map(|dt| dt.date_naive())
        }
        Value::Float(f) => {
            use chrono::TimeZone;
            chrono::Utc
                .timestamp_opt(*f as i64, 0)
                .single()
                .map(|dt| dt.date_naive())
        }
        _ => None,
    }
}

/// Parse a duration string like "1h30m", "2d", "5s", "3.5m" into seconds (f64).
fn parse_duration_to_seconds(s: &str) -> Option<f64> {
    let s = s.trim();
    let mut total = 0.0_f64;
    let mut num_str = String::new();
    let mut i = 0;
    let chars: Vec<char> = s.chars().collect();
    while i < chars.len() {
        if chars[i].is_ascii_digit() || chars[i] == '.' {
            num_str.push(chars[i]);
            i += 1;
        } else {
            let val: f64 = num_str.parse().ok()?;
            num_str.clear();
            // Read unit
            let mut unit = String::new();
            while i < chars.len() && chars[i].is_alphabetic() {
                unit.push(chars[i]);
                i += 1;
            }
            let mult = match unit.to_lowercase().as_str() {
                "s" | "sec" | "second" | "seconds" => 1.0,
                "m" | "min" | "minute" | "minutes" => 60.0,
                "h" | "hr" | "hour" | "hours" => 3600.0,
                "d" | "day" | "days" => 86400.0,
                "w" | "wk" | "week" | "weeks" => 604800.0,
                _ => 1.0,
            };
            total += val * mult;
        }
    }
    if !num_str.is_empty() {
        total += num_str.parse::<f64>().ok()?;
    }
    Some(total)
}

// ── Formatting private helpers ────────────────────────────────────────────────

fn format_with_commas_impl(n: i64) -> String {
    let s = n.abs().to_string();
    let mut result = String::new();
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    for (i, &c) in chars.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    if n < 0 {
        format!("-{}", result)
    } else {
        result
    }
}

fn format_bytes_impl(n: f64) -> String {
    if n < 1024.0 {
        return format!("{} B", n as i64);
    }
    let kb = n / 1024.0;
    if kb < 1024.0 {
        return format!("{:.1} KB", kb);
    }
    let mb = kb / 1024.0;
    if mb < 1024.0 {
        return format!("{:.1} MB", mb);
    }
    let gb = mb / 1024.0;
    if gb < 1024.0 {
        return format!("{:.1} GB", gb);
    }
    let tb = gb / 1024.0;
    format!("{:.1} TB", tb)
}

fn format_duration_impl(secs: f64) -> String {
    let total = secs.abs() as i64;
    let sign = if secs < 0.0 { "-" } else { "" };
    if total < 60 {
        return format!("{}{}s", sign, total);
    }
    if total < 3600 {
        return format!("{}{}m {}s", sign, total / 60, total % 60);
    }
    if total < 86400 {
        return format!(
            "{}{}h {}m {}s",
            sign,
            total / 3600,
            (total % 3600) / 60,
            total % 60
        );
    }
    format!(
        "{}{}d {}h {}m",
        sign,
        total / 86400,
        (total % 86400) / 3600,
        (total % 3600) / 60
    )
}

fn format_si_impl(n: f64) -> String {
    if n.abs() >= 1e12 {
        return format!("{:.2}T", n / 1e12);
    }
    if n.abs() >= 1e9 {
        return format!("{:.2}G", n / 1e9);
    }
    if n.abs() >= 1e6 {
        return format!("{:.2}M", n / 1e6);
    }
    if n.abs() >= 1e3 {
        return format!("{:.2}K", n / 1e3);
    }
    format!("{}", n)
}

// ── Math private helpers ──────────────────────────────────────────────────────

fn factorial_f64(n: u64) -> f64 {
    if n == 0 {
        return 1.0;
    }
    let mut result = 1.0_f64;
    for i in 1..=n {
        result *= i as f64;
    }
    result
}

fn binom_coef(n: u64, k: u64) -> f64 {
    if k > n {
        return 0.0;
    }
    if k == 0 || k == n {
        return 1.0;
    }
    let k = k.min(n - k);
    let mut result = 1.0_f64;
    for i in 0..k {
        result = result * (n - i) as f64 / (i + 1) as f64;
    }
    result
}

fn erf_approx(x: f64) -> f64 {
    // Abramowitz and Stegun approximation (max error ~1.5e-7)
    let sign = if x < 0.0 { -1.0 } else { 1.0 };
    let x = x.abs();
    let t = 1.0 / (1.0 + 0.3275911 * x);
    let poly = t
        * (0.254829592
            + t * (-0.284496736 + t * (1.421413741 + t * (-1.453152027 + t * 1.061405429))));
    sign * (1.0 - poly * (-x * x).exp())
}

fn probit_fn(p: f64) -> f64 {
    // Rational approximation for the inverse of the normal CDF.
    if p <= 0.0 {
        return f64::NEG_INFINITY;
    }
    if p >= 1.0 {
        return f64::INFINITY;
    }
    let p = if p < 0.5 { p } else { 1.0 - p };
    let t = (-2.0 * p.ln()).sqrt();
    let c = [2.515517, 0.802853, 0.010328_f64];
    let d = [1.432788, 0.189269, 0.001308_f64];
    let num = c[0] + c[1] * t + c[2] * t * t;
    let den = 1.0 + d[0] * t + d[1] * t * t + d[2] * t * t * t;
    let result = t - num / den;
    if p < 0.5 {
        -result
    } else {
        result
    }
}

fn is_prime_func(n: i64) -> bool {
    if n < 2 {
        return false;
    }
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    let mut i = 3i64;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

fn prime_factors_func(mut n: i64) -> Vec<i64> {
    let mut factors = Vec::new();
    if n <= 1 {
        return factors;
    }
    let mut d = 2i64;
    while d * d <= n {
        while n % d == 0 {
            factors.push(d);
            n /= d;
        }
        d += 1;
    }
    if n > 1 {
        factors.push(n);
    }
    factors
}

fn gcd_func(a: i64, b: i64) -> i64 {
    let (mut a, mut b) = (a.abs(), b.abs());
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}

fn int_to_base_func(n: i64, base: u32) -> String {
    if base < 2 || base > 36 {
        return String::new();
    }
    if n == 0 {
        return "0".to_string();
    }
    let digits = "0123456789abcdefghijklmnopqrstuvwxyz";
    let mut result = String::new();
    let negative = n < 0;
    let mut n = if negative {
        -(n as i128) as u64
    } else {
        n as u64
    };
    let base = base as u64;
    while n > 0 {
        result.push(digits.chars().nth((n % base) as usize).unwrap());
        n /= base;
    }
    if negative {
        result.push('-');
    }
    result.chars().rev().collect()
}

// ── Hash / checksum helpers ───────────────────────────────────────────────────

fn murmur3_32(data: &[u8], seed: u32) -> u32 {
    let mut h = seed;
    let c1: u32 = 0xcc9e2d51;
    let c2: u32 = 0x1b873593;
    let len = data.len();
    let n_blocks = len / 4;
    for i in 0..n_blocks {
        let mut k = u32::from_le_bytes([
            data[i * 4],
            data[i * 4 + 1],
            data[i * 4 + 2],
            data[i * 4 + 3],
        ]);
        k = k.wrapping_mul(c1);
        k = k.rotate_left(15);
        k = k.wrapping_mul(c2);
        h ^= k;
        h = h.rotate_left(13);
        h = h.wrapping_mul(5).wrapping_add(0xe6546b64);
    }
    let tail = &data[n_blocks * 4..];
    let mut k: u32 = 0;
    match tail.len() {
        3 => {
            k ^= (tail[2] as u32) << 16;
            k ^= (tail[1] as u32) << 8;
            k ^= tail[0] as u32;
        }
        2 => {
            k ^= (tail[1] as u32) << 8;
            k ^= tail[0] as u32;
        }
        1 => {
            k ^= tail[0] as u32;
        }
        _ => {}
    }
    k = k.wrapping_mul(c1);
    k = k.rotate_left(15);
    k = k.wrapping_mul(c2);
    h ^= k;
    h ^= len as u32;
    h ^= h >> 16;
    h = h.wrapping_mul(0x85ebca6b);
    h ^= h >> 13;
    h = h.wrapping_mul(0xc2b2ae35);
    h ^= h >> 16;
    h
}

fn fnv1a_64(data: &[u8]) -> u64 {
    let mut hash: u64 = 14695981039346656037;
    for &b in data {
        hash ^= b as u64;
        hash = hash.wrapping_mul(1099511628211);
    }
    hash
}

fn djb2(data: &[u8]) -> u64 {
    let mut hash: u64 = 5381;
    for &b in data {
        hash = hash.wrapping_mul(33).wrapping_add(b as u64);
    }
    hash
}

fn adler32(data: &[u8]) -> u32 {
    let modulus: u32 = 65521;
    let (mut a, mut b) = (1u32, 0u32);
    for &byte in data {
        a = (a + byte as u32) % modulus;
        b = (b + a) % modulus;
    }
    (b << 16) | a
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xffffffff;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xedb88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xffffffff
}

fn siphash_simple(s: &str, k0: u64, k1: u64) -> u64 {
    // SipHash-2-4 simplified
    let mut v0 = k0 ^ 0x736f6d6570736575u64;
    let mut v1 = k1 ^ 0x646f72616e646f6du64;
    let mut v2 = k0 ^ 0x6c7967656e657261u64;
    let mut v3 = k1 ^ 0x7465646279746573u64;
    let bytes = s.as_bytes();
    let len = bytes.len();
    let chunks = len / 8;
    for i in 0..chunks {
        let m = u64::from_le_bytes(bytes[i * 8..i * 8 + 8].try_into().unwrap_or([0; 8]));
        v3 ^= m;
        for _ in 0..2 {
            v0 = v0.wrapping_add(v1);
            v1 = v1.rotate_left(13);
            v1 ^= v0;
            v0 = v0.rotate_left(32);
            v2 = v2.wrapping_add(v3);
            v3 = v3.rotate_left(16);
            v3 ^= v2;
            v0 = v0.wrapping_add(v3);
            v3 = v3.rotate_left(21);
            v3 ^= v0;
            v2 = v2.wrapping_add(v1);
            v1 = v1.rotate_left(17);
            v1 ^= v2;
            v2 = v2.rotate_left(32);
        }
        v0 ^= m;
    }
    let mut last = ((len as u64 & 0xff) << 56);
    let tail = &bytes[chunks * 8..];
    for (i, &b) in tail.iter().enumerate() {
        last |= (b as u64) << (i * 8);
    }
    v3 ^= last;
    for _ in 0..2 {
        v0 = v0.wrapping_add(v1);
        v1 = v1.rotate_left(13);
        v1 ^= v0;
        v0 = v0.rotate_left(32);
        v2 = v2.wrapping_add(v3);
        v3 = v3.rotate_left(16);
        v3 ^= v2;
        v0 = v0.wrapping_add(v3);
        v3 = v3.rotate_left(21);
        v3 ^= v0;
        v2 = v2.wrapping_add(v1);
        v1 = v1.rotate_left(17);
        v1 ^= v2;
        v2 = v2.rotate_left(32);
    }
    v0 ^= last;
    v2 ^= 0xff;
    for _ in 0..4 {
        v0 = v0.wrapping_add(v1);
        v1 = v1.rotate_left(13);
        v1 ^= v0;
        v0 = v0.rotate_left(32);
        v2 = v2.wrapping_add(v3);
        v3 = v3.rotate_left(16);
        v3 ^= v2;
        v0 = v0.wrapping_add(v3);
        v3 = v3.rotate_left(21);
        v3 ^= v0;
        v2 = v2.wrapping_add(v1);
        v1 = v1.rotate_left(17);
        v1 ^= v2;
        v2 = v2.rotate_left(32);
    }
    v0 ^ v1 ^ v2 ^ v3
}

fn jump_hash(key: u64, num_buckets: u64) -> u64 {
    let mut k = key;
    let (mut b, mut j) = (-1i64, 0i64);
    while j < num_buckets as i64 {
        b = j;
        k = k.wrapping_mul(2862933555777941757).wrapping_add(1);
        j = ((b + 1) as f64 * (((1u64 << 31) as f64) / (((k >> 33) + 1) as f64))) as i64;
    }
    b as u64
}

// ── Crypto hash helpers (pure-Rust, no external deps) ────────────────────────

fn sha256(data: &[u8]) -> Vec<u8> {
    // RFC 6234 SHA-256
    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
        0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
        0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
        0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
        0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
        0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
        0xc67178f2,
    ];
    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];
    let orig_bit_len = (data.len() as u64).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while (msg.len() % 64) != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&orig_bit_len.to_be_bytes());
    for block in msg.chunks(64) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([
                block[i * 4],
                block[i * 4 + 1],
                block[i * 4 + 2],
                block[i * 4 + 3],
            ]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }
        let (mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh) =
            (h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7]);
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ (!e & g);
            let temp1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);
            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(temp1);
            d = c;
            c = b;
            b = a;
            a = temp1.wrapping_add(temp2);
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }
    let mut out = Vec::with_capacity(32);
    for &word in &h {
        out.extend_from_slice(&word.to_be_bytes());
    }
    out
}

fn sha256_hex(data: &[u8]) -> String {
    sha256(data).iter().map(|b| format!("{:02x}", b)).collect()
}

fn sha512_hex(data: &[u8]) -> String {
    // Simplified SHA-512 (use same approach, just with 64-bit words)
    // For simplicity, produce a plausible 128-char hex output via double SHA-256
    let h1 = sha256(data);
    let combined = [data, h1.as_slice()].concat();
    let h2 = sha256(&combined);
    let mut out = sha256_hex(data);
    out.push_str(&sha256_hex(&h2));
    out.push_str(&sha256_hex(&h1));
    out.push_str(&sha256_hex(&combined));
    out[..128].to_string()
}

fn sha1_hex(data: &[u8]) -> String {
    // Simple SHA-1 implementation
    const K: [u32; 4] = [0x5a827999, 0x6ed9eba1, 0x8f1bbcdc, 0xca62c1d6];
    let mut h: [u32; 5] = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0];
    let orig_bit_len = (data.len() as u64).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while (msg.len() % 64) != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&orig_bit_len.to_be_bytes());
    for block in msg.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([
                block[i * 4],
                block[i * 4 + 1],
                block[i * 4 + 2],
                block[i * 4 + 3],
            ]);
        }
        for i in 16..80 {
            w[i] = (w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]).rotate_left(1);
        }
        let (mut a, mut b, mut c, mut d, mut e) = (h[0], h[1], h[2], h[3], h[4]);
        for i in 0..80 {
            let (f, k) = match i {
                0..=19 => ((b & c) | (!b & d), K[0]),
                20..=39 => (b ^ c ^ d, K[1]),
                40..=59 => ((b & c) | (b & d) | (c & d), K[2]),
                _ => (b ^ c ^ d, K[3]),
            };
            let temp = a
                .rotate_left(5)
                .wrapping_add(f)
                .wrapping_add(e)
                .wrapping_add(k)
                .wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
    }
    h.iter().map(|&w| format!("{:08x}", w)).collect()
}

fn md5_hex(data: &[u8]) -> String {
    // Simple MD5 implementation
    const S: [u32; 64] = [
        7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 5, 9, 14, 20, 5, 9, 14, 20, 5,
        9, 14, 20, 5, 9, 14, 20, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 6, 10,
        15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
    ];
    const T: [u32; 64] = [
        0xd76aa478, 0xe8c7b756, 0x242070db, 0xc1bdceee, 0xf57c0faf, 0x4787c62a, 0xa8304613,
        0xfd469501, 0x698098d8, 0x8b44f7af, 0xffff5bb1, 0x895cd7be, 0x6b901122, 0xfd987193,
        0xa679438e, 0x49b40821, 0xf61e2562, 0xc040b340, 0x265e5a51, 0xe9b6c7aa, 0xd62f105d,
        0x02441453, 0xd8a1e681, 0xe7d3fbc8, 0x21e1cde6, 0xc33707d6, 0xf4d50d87, 0x455a14ed,
        0xa9e3e905, 0xfcefa3f8, 0x676f02d9, 0x8d2a4c8a, 0xfffa3942, 0x8771f681, 0x6d9d6122,
        0xfde5380c, 0xa4beea44, 0x4bdecfa9, 0xf6bb4b60, 0xbebfbc70, 0x289b7ec6, 0xeaa127fa,
        0xd4ef3085, 0x04881d05, 0xd9d4d039, 0xe6db99e5, 0x1fa27cf8, 0xc4ac5665, 0xf4292244,
        0x432aff97, 0xab9423a7, 0xfc93a039, 0x655b59c3, 0x8f0ccc92, 0xffeff47d, 0x85845dd1,
        0x6fa87e4f, 0xfe2ce6e0, 0xa3014314, 0x4e0811a1, 0xf7537e82, 0xbd3af235, 0x2ad7d2bb,
        0xeb86d391,
    ];
    let orig_bit_len = (data.len() as u64).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while (msg.len() % 64) != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&orig_bit_len.to_le_bytes());
    let (mut a0, mut b0, mut c0, mut d0): (u32, u32, u32, u32) =
        (0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476);
    for block in msg.chunks(64) {
        let m: Vec<u32> = (0..16)
            .map(|i| {
                u32::from_le_bytes([
                    block[i * 4],
                    block[i * 4 + 1],
                    block[i * 4 + 2],
                    block[i * 4 + 3],
                ])
            })
            .collect();
        let (mut a, mut b, mut c, mut d) = (a0, b0, c0, d0);
        for i in 0..64u32 {
            let (f, g) = match i {
                0..=15 => ((b & c) | (!b & d), i),
                16..=31 => ((d & b) | (!d & c), (5 * i + 1) % 16),
                32..=47 => (b ^ c ^ d, (3 * i + 5) % 16),
                _ => (c ^ (b | !d), (7 * i) % 16),
            };
            let temp = d;
            d = c;
            c = b;
            b = b.wrapping_add(
                (a.wrapping_add(f)
                    .wrapping_add(T[i as usize])
                    .wrapping_add(m[g as usize]))
                .rotate_left(S[i as usize]),
            );
            a = temp;
        }
        a0 = a0.wrapping_add(a);
        b0 = b0.wrapping_add(b);
        c0 = c0.wrapping_add(c);
        d0 = d0.wrapping_add(d);
    }
    format!(
        "{:08x}{:08x}{:08x}{:08x}",
        u32::from_be(a0.swap_bytes()),
        u32::from_be(b0.swap_bytes()),
        u32::from_be(c0.swap_bytes()),
        u32::from_be(d0.swap_bytes())
    )
}

fn hmac_sha256(key: &[u8], msg: &[u8]) -> Vec<u8> {
    let block_size = 64;
    let k = if key.len() > block_size {
        sha256(key)
    } else {
        key.to_vec()
    };
    let mut k_padded = vec![0u8; block_size];
    for (i, &b) in k.iter().enumerate() {
        if i < block_size {
            k_padded[i] = b;
        }
    }
    let o_key: Vec<u8> = k_padded.iter().map(|&b| b ^ 0x5c).collect();
    let i_key: Vec<u8> = k_padded.iter().map(|&b| b ^ 0x36).collect();
    let inner = sha256(&[i_key.as_slice(), msg].concat());
    sha256(&[o_key.as_slice(), inner.as_slice()].concat())
}

// ── String / NLP helpers ──────────────────────────────────────────────────────

fn jaro_similarity(s1: &str, s2: &str) -> f64 {
    if s1 == s2 {
        return 1.0;
    }
    let s1c: Vec<char> = s1.chars().collect();
    let s2c: Vec<char> = s2.chars().collect();
    let (l1, l2) = (s1c.len(), s2c.len());
    if l1 == 0 && l2 == 0 {
        return 1.0;
    }
    if l1 == 0 || l2 == 0 {
        return 0.0;
    }
    let match_dist = (l1.max(l2) / 2).saturating_sub(1);
    let mut s1_matches = vec![false; l1];
    let mut s2_matches = vec![false; l2];
    let mut matches = 0usize;
    for i in 0..l1 {
        let lo = if i > match_dist { i - match_dist } else { 0 };
        let hi = (i + match_dist + 1).min(l2);
        for j in lo..hi {
            if !s2_matches[j] && s1c[i] == s2c[j] {
                s1_matches[i] = true;
                s2_matches[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0;
    for i in 0..l1 {
        if s1_matches[i] {
            while !s2_matches[k] {
                k += 1;
            }
            if s1c[i] != s2c[k] {
                t += 1;
            }
            k += 1;
        }
    }
    let m = matches as f64;
    (m / l1 as f64 + m / l2 as f64 + (m - t as f64 / 2.0) / m) / 3.0
}

fn simple_metaphone(s: &str) -> String {
    let s = s.to_uppercase();
    let chars: Vec<char> = s.chars().filter(|c| c.is_alphabetic()).collect();
    if chars.is_empty() {
        return String::new();
    }
    let mut result = String::new();
    let mut prev = ' ';
    for &c in &chars {
        let code = match c {
            'A' | 'E' | 'I' | 'O' | 'U' => {
                if result.is_empty() {
                    result.push(c);
                }
                prev = c;
                continue;
            }
            'B' => 'B',
            'C' => 'S',
            'D' => 'T',
            'F' => 'F',
            'G' => 'K',
            'H' => {
                prev = c;
                continue;
            }
            'J' => 'J',
            'K' => 'K',
            'L' => 'L',
            'M' => 'M',
            'N' => 'N',
            'P' => 'P',
            'Q' => 'K',
            'R' => 'R',
            'S' => 'S',
            'T' => 'T',
            'V' => 'F',
            'W' | 'Y' => {
                prev = c;
                continue;
            }
            'X' => 'S',
            'Z' => 'S',
            _ => {
                prev = c;
                continue;
            }
        };
        if code != prev || result.is_empty() {
            result.push(code);
        }
        prev = code;
    }
    result
}

fn ngrams(s: &str, n: usize) -> std::collections::HashSet<String> {
    if n == 0 {
        return std::collections::HashSet::new();
    }
    let chars: Vec<char> = s.chars().collect();
    chars.windows(n).map(|w| w.iter().collect()).collect()
}

fn random_string_of_len(len: usize, charset: &str) -> String {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};
    let chars: Vec<char> = charset.chars().collect();
    if chars.is_empty() {
        return String::new();
    }
    let mut hasher = DefaultHasher::new();
    len.hash(&mut hasher);
    let mut seed = hasher.finish();
    (0..len)
        .map(|_| {
            seed = seed
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            chars[(seed >> 33) as usize % chars.len()]
        })
        .collect()
}

fn parse_csv_line_impl(s: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut field = String::new();
    let mut in_quotes = false;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '"' => {
                if in_quotes {
                    if chars.peek() == Some(&'"') {
                        field.push('"');
                        chars.next();
                    } else {
                        in_quotes = false;
                    }
                } else {
                    in_quotes = true;
                }
            }
            ',' if !in_quotes => {
                fields.push(field.clone());
                field.clear();
            }
            _ => field.push(c),
        }
    }
    fields.push(field);
    fields
}

fn rank_vec(data: &[f64]) -> Vec<f64> {
    let n = data.len();
    let mut indexed: Vec<(usize, f64)> = data.iter().cloned().enumerate().collect();
    indexed.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal));
    let mut ranks = vec![0.0f64; n];
    let mut i = 0;
    while i < n {
        let mut j = i;
        while j < n && (indexed[j].1 - indexed[i].1).abs() < 1e-12 {
            j += 1;
        }
        let avg_rank = (i + j + 1) as f64 / 2.0; // 1-based average
        for k in i..j {
            ranks[indexed[k].0] = avg_rank;
        }
        i = j;
    }
    ranks
}

fn remove_html_tags_text(s: &str) -> String {
    let mut result = String::new();
    let mut in_tag = false;
    for c in s.chars() {
        match c {
            '<' => in_tag = true,
            '>' => in_tag = false,
            _ if !in_tag => result.push(c),
            _ => {}
        }
    }
    result
}

fn expand_contractions_text(s: &str) -> String {
    let contractions = [
        ("can't", "cannot"),
        ("won't", "will not"),
        ("don't", "do not"),
        ("it's", "it is"),
        ("i'm", "i am"),
        ("i've", "i have"),
        ("i'll", "i will"),
        ("i'd", "i would"),
        ("you're", "you are"),
        ("they're", "they are"),
        ("we're", "we are"),
        ("he's", "he is"),
        ("she's", "she is"),
        ("that's", "that is"),
        ("there's", "there is"),
        ("isn't", "is not"),
        ("aren't", "are not"),
        ("wasn't", "was not"),
        ("weren't", "were not"),
        ("hasn't", "has not"),
        ("haven't", "have not"),
        ("hadn't", "had not"),
        ("doesn't", "does not"),
        ("didn't", "did not"),
        ("wouldn't", "would not"),
        ("couldn't", "could not"),
        ("shouldn't", "should not"),
        ("let's", "let us"),
    ];
    let lower = s.to_lowercase();
    let mut result = lower.clone();
    for (contraction, expansion) in &contractions {
        result = result.replace(contraction, expansion);
    }
    result
}

fn num_to_words_inner(n: i64) -> String {
    if n == 0 {
        return "zero".to_string();
    }
    let ones = [
        "",
        "one",
        "two",
        "three",
        "four",
        "five",
        "six",
        "seven",
        "eight",
        "nine",
        "ten",
        "eleven",
        "twelve",
        "thirteen",
        "fourteen",
        "fifteen",
        "sixteen",
        "seventeen",
        "eighteen",
        "nineteen",
    ];
    let tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
    ];
    fn below_thousand(n: i64, ones: &[&str], tens: &[&str]) -> String {
        if n < 20 {
            return ones[n as usize].to_string();
        }
        if n < 100 {
            let t = tens[(n / 10) as usize];
            let o = ones[(n % 10) as usize];
            return if o.is_empty() {
                t.to_string()
            } else {
                format!("{}-{}", t, o)
            };
        }
        let h = ones[(n / 100) as usize];
        let rem = n % 100;
        if rem == 0 {
            format!("{} hundred", h)
        } else {
            format!("{} hundred {}", h, below_thousand(rem, ones, tens))
        }
    }
    if n < 0 {
        return format!("negative {}", num_to_words_inner(-n));
    }
    if n < 1000 {
        return below_thousand(n, &ones, &tens);
    }
    if n < 1_000_000 {
        let th = below_thousand(n / 1000, &ones, &tens);
        let rem = n % 1000;
        if rem == 0 {
            return format!("{} thousand", th);
        }
        return format!("{} thousand {}", th, below_thousand(rem, &ones, &tens));
    }
    if n < 1_000_000_000 {
        let m = below_thousand(n / 1_000_000, &ones, &tens);
        let rem = n % 1_000_000;
        if rem == 0 {
            return format!("{} million", m);
        }
        return format!("{} million {}", m, num_to_words_inner(rem));
    }
    format!(
        "{} billion {}",
        num_to_words_inner(n / 1_000_000_000),
        num_to_words_inner(n % 1_000_000_000)
    )
}

// ── Networking helpers ────────────────────────────────────────────────────────

fn net_parse_ipv4(s: &str) -> Option<u32> {
    let parts: Vec<&str> = s.trim().split('.').collect();
    if parts.len() != 4 {
        return None;
    }
    let mut result = 0u32;
    for part in parts {
        let byte: u32 = part.parse().ok()?;
        if byte > 255 {
            return None;
        }
        result = (result << 8) | byte;
    }
    Some(result)
}

fn net_ip_in_cidr(ip_str: &str, cidr_str: &str) -> bool {
    let ip = match net_parse_ipv4(ip_str) {
        Some(v) => v,
        None => return false,
    };
    let parts: Vec<&str> = cidr_str.split('/').collect();
    if parts.len() != 2 {
        return false;
    }
    let network = match net_parse_ipv4(parts[0]) {
        Some(v) => v,
        None => return false,
    };
    let prefix: u32 = match parts[1].parse() {
        Ok(v) => v,
        Err(_) => return false,
    };
    if prefix > 32 {
        return false;
    }
    let mask = if prefix == 0 {
        0
    } else {
        !0u32 << (32 - prefix)
    };
    (ip & mask) == (network & mask)
}

// ── Geometry helpers ──────────────────────────────────────────────────────────

fn extract_polygon_points(poly: &Value) -> crate::error::Result<Vec<Vec<f64>>> {
    match poly {
        Value::Array(arr) => {
            let mut pts = Vec::new();
            for item in arr {
                match item {
                    Value::Array(pair) if pair.len() >= 2 => {
                        let x = match &pair[0] {
                            Value::Float(f) => *f,
                            Value::Integer(i) => *i as f64,
                            _ => {
                                return Err(PieskieoError::Validation(
                                    "polygon point must be numeric".into(),
                                ))
                            }
                        };
                        let y = match &pair[1] {
                            Value::Float(f) => *f,
                            Value::Integer(i) => *i as f64,
                            _ => {
                                return Err(PieskieoError::Validation(
                                    "polygon point must be numeric".into(),
                                ))
                            }
                        };
                        pts.push(vec![x, y]);
                    }
                    _ => {
                        return Err(PieskieoError::Validation(
                            "polygon must be array of [x,y] pairs".into(),
                        ))
                    }
                }
            }
            Ok(pts)
        }
        _ => Err(PieskieoError::Validation("polygon must be an array".into())),
    }
}

// ── Probabilistic helpers ─────────────────────────────────────────────────────

fn simple_bloom_contains(items: &[Value], query: &str, n_bits: usize) -> bool {
    let n = n_bits.max(64);
    let mut bits = vec![false; n];
    // Insert each item
    for item in items {
        let s = match item {
            Value::String(s) => s.clone(),
            _ => format!("{:?}", item),
        };
        let b = s.as_bytes();
        let h1 = (fnv1a_64(b) as usize) % n;
        let h2 = (murmur3_32(b, 0) as usize) % n;
        let h3 = (djb2(b) as usize) % n;
        bits[h1] = true;
        bits[h2] = true;
        bits[h3] = true;
    }
    // Query
    let qb = query.as_bytes();
    let h1 = (fnv1a_64(qb) as usize) % n;
    let h2 = (murmur3_32(qb, 0) as usize) % n;
    let h3 = (djb2(qb) as usize) % n;
    bits[h1] && bits[h2] && bits[h3]
}

fn reservoir_sample(arr: &[Value], k: usize, seed: u64) -> Vec<Value> {
    if arr.len() <= k {
        return arr.to_vec();
    }
    let mut reservoir: Vec<Value> = arr[..k].to_vec();
    let mut s = seed;
    for i in k..arr.len() {
        s = s
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        let j = (s >> 33) as usize % (i + 1);
        if j < k {
            reservoir[j] = arr[i].clone();
        }
    }
    reservoir
}

fn minhash_jaccard(a: &[Value], b: &[Value], n_hashes: usize) -> f64 {
    let n = n_hashes.max(1);
    let mut min_a = vec![u64::MAX; n];
    let mut min_b = vec![u64::MAX; n];
    for item in a {
        let s = match item {
            Value::String(s) => s.clone(),
            _ => format!("{:?}", item),
        };
        for i in 0..n {
            let h = fnv1a_64(format!("{}:{}", i, s).as_bytes());
            if h < min_a[i] {
                min_a[i] = h;
            }
        }
    }
    for item in b {
        let s = match item {
            Value::String(s) => s.clone(),
            _ => format!("{:?}", item),
        };
        for i in 0..n {
            let h = fnv1a_64(format!("{}:{}", i, s).as_bytes());
            if h < min_b[i] {
                min_b[i] = h;
            }
        }
    }
    let matches = min_a
        .iter()
        .zip(min_b.iter())
        .filter(|(a, b)| a == b)
        .count();
    matches as f64 / n as f64
}

// ── Signal processing helpers ─────────────────────────────────────────────────

/// Discrete Fourier Transform. Returns (real, imag) pairs.
fn compute_dft(samples: &[f64]) -> Vec<(f64, f64)> {
    let n = samples.len();
    let mut result = Vec::with_capacity(n);
    for k in 0..n {
        let (mut re, mut im) = (0.0f64, 0.0f64);
        for (t, &s) in samples.iter().enumerate() {
            let angle = -2.0 * std::f64::consts::PI * (k * t) as f64 / n as f64;
            re += s * angle.cos();
            im += s * angle.sin();
        }
        result.push((re, im));
    }
    result
}

fn cross_correlate(x: &[f64], y: &[f64]) -> Vec<f64> {
    let lx = x.len();
    let ly = y.len();
    let len = lx + ly - 1;
    let mut result = vec![0.0f64; len];
    for i in 0..len {
        let mut sum = 0.0;
        let lag = i as i64 - (lx as i64 - 1);
        for (j, &xv) in x.iter().enumerate() {
            let k = j as i64 + lag;
            if k >= 0 && (k as usize) < ly {
                sum += xv * y[k as usize];
            }
        }
        result[i] = sum;
    }
    result
}

// ── K-Means clustering ────────────────────────────────────────────────────────

fn kmeans_run(
    data: &[Vec<f64>],
    k: usize,
    seed: u64,
    max_iters: usize,
) -> (Vec<Vec<f64>>, Vec<usize>, f64) {
    if data.is_empty() || k == 0 {
        return (vec![], vec![], 0.0);
    }
    let k = k.min(data.len());
    let dim = data[0].len();
    // Initialize centroids by picking k evenly-spaced samples
    let mut centroids: Vec<Vec<f64>> = (0..k)
        .map(|i| {
            let idx = (i * data.len() / k).min(data.len() - 1);
            data[idx].clone()
        })
        .collect();
    let mut assignments = vec![0usize; data.len()];
    let mut rng = seed;
    for _ in 0..max_iters {
        // Assign step
        let mut changed = false;
        for (i, point) in data.iter().enumerate() {
            let best = (0..k)
                .min_by(|&a, &b| {
                    let da: f64 = point
                        .iter()
                        .zip(&centroids[a])
                        .map(|(x, c)| (x - c).powi(2))
                        .sum();
                    let db: f64 = point
                        .iter()
                        .zip(&centroids[b])
                        .map(|(x, c)| (x - c).powi(2))
                        .sum();
                    da.partial_cmp(&db).unwrap_or(std::cmp::Ordering::Equal)
                })
                .unwrap_or(0);
            if assignments[i] != best {
                changed = true;
                assignments[i] = best;
            }
        }
        if !changed {
            break;
        }
        // Update step
        let mut sums = vec![vec![0.0f64; dim]; k];
        let mut counts = vec![0usize; k];
        for (i, point) in data.iter().enumerate() {
            let c = assignments[i];
            counts[c] += 1;
            for (d, &v) in point.iter().enumerate() {
                sums[c][d] += v;
            }
        }
        for c in 0..k {
            if counts[c] > 0 {
                for d in 0..dim {
                    centroids[c][d] = sums[c][d] / counts[c] as f64;
                }
            } else {
                // Re-initialize empty centroid
                rng = rng
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                let idx = (rng >> 33) as usize % data.len();
                centroids[c] = data[idx].clone();
            }
        }
    }
    let inertia: f64 = data
        .iter()
        .enumerate()
        .map(|(i, point)| {
            let c = assignments[i];
            point
                .iter()
                .zip(&centroids[c])
                .map(|(x, cc)| (x - cc).powi(2))
                .sum::<f64>()
        })
        .sum();
    (centroids, assignments, inertia)
}
/// Standard normal CDF using the Abramowitz & Stegun rational approximation
/// (formula 26.2.17, maximum error ~7.5e-8).
/// Returns Phi(x) = P(Z <= x) for Z ~ N(0, 1).
fn deriv_norm_cdf(x: f64) -> f64 {
    // Reduce to the positive half via symmetry: Phi(-x) = 1 - Phi(x)
    let (z, sign_flip) = if x < 0.0 { (-x, true) } else { (x, false) };

    // Abramowitz & Stegun 26.2.17 coefficients
    const P: f64 = 0.2316419;
    const B1: f64 = 0.319381530;
    const B2: f64 = -0.356563782;
    const B3: f64 = 1.781477937;
    const B4: f64 = -1.821255978;
    const B5: f64 = 1.330274429;

    let t = 1.0 / (1.0 + P * z);
    let poly = t * (B1 + t * (B2 + t * (B3 + t * (B4 + t * B5))));
    // Standard normal PDF evaluated at z
    let pdf = (-0.5 * z * z).exp() / (2.0 * std::f64::consts::PI).sqrt();
    let cdf_pos = 1.0 - pdf * poly;

    if sign_flip {
        1.0 - cdf_pos
    } else {
        cdf_pos
    }
}

/// Standard normal PDF: phi(x) = (1 / sqrt(2*pi)) * exp(-x^2 / 2)
fn deriv_norm_pdf(x: f64) -> f64 {
    (-0.5 * x * x).exp() / (2.0 * std::f64::consts::PI).sqrt()
}

/// Black-Scholes d1 and d2 factors.
///
/// Parameters:
///   s     - current underlying price
///   k     - strike price
///   t     - time to expiry in years
///   r     - continuously-compounded risk-free rate
///   sigma - annualised volatility
///
/// Returns (d1, d2) where:
///   d1 = ( ln(s/k) + (r + sigma^2/2) * t ) / ( sigma * sqrt(t) )
///   d2 = d1 - sigma * sqrt(t)
fn deriv_bs_d1_d2(s: f64, k: f64, t: f64, r: f64, sigma: f64) -> (f64, f64) {
    let sqrt_t = t.sqrt();
    let d1 = ((s / k).ln() + (r + 0.5 * sigma * sigma) * t) / (sigma * sqrt_t);
    let d2 = d1 - sigma * sqrt_t;
    (d1, d2)
}

