fn str_to_camel_case(s: &str) -> String {
    let mut result = String::new();
    let mut capitalize_next = false;
    let mut first_word = true;
    for c in s.chars() {
        if c == '_' || c == '-' {
            capitalize_next = true;
        } else if capitalize_next {
            if first_word {
                // First segment stays lowercase for camelCase (lower camel)
                result.push(c.to_ascii_lowercase());
            } else {
                result.extend(c.to_uppercase());
            }
            capitalize_next = false;
            first_word = false;
        } else {
            if first_word {
                result.push(c.to_ascii_lowercase());
            } else {
                result.push(c);
            }
            first_word = false;
        }
    }
    // Post-process: first segment should already be lowercase;
    // if the input started with a separator the result is correct.
    result
}

fn str_to_snake_case(s: &str) -> String {
    let mut result = String::new();
    let chars: Vec<char> = s.chars().collect();
    for (i, &c) in chars.iter().enumerate() {
        if c == '-' || c == ' ' {
            result.push('_');
        } else if c.is_ascii_uppercase() {
            if i > 0
                && (chars[i - 1].is_ascii_lowercase()
                    || chars[i - 1].is_ascii_digit()
                    || (i + 1 < chars.len() && chars[i + 1].is_ascii_lowercase()))
            {
                result.push('_');
            }
            result.push(c.to_ascii_lowercase());
        } else {
            result.push(c);
        }
    }
    result
}

fn str_deburr(s: &str) -> String {
    s.chars()
        .map(|c| match c {
            'À' | 'Á' | 'Â' | 'Ã' | 'Ä' | 'Å' => 'A',
            'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' => 'a',
            'Æ' => 'A',
            'æ' => 'a',
            'Ç' => 'C',
            'ç' => 'c',
            'È' | 'É' | 'Ê' | 'Ë' => 'E',
            'è' | 'é' | 'ê' | 'ë' => 'e',
            'Ì' | 'Í' | 'Î' | 'Ï' => 'I',
            'ì' | 'í' | 'î' | 'ï' => 'i',
            'Ð' => 'D',
            'ð' => 'd',
            'Ñ' => 'N',
            'ñ' => 'n',
            'Ò' | 'Ó' | 'Ô' | 'Õ' | 'Ö' | 'Ø' => 'O',
            'ò' | 'ó' | 'ô' | 'õ' | 'ö' | 'ø' => 'o',
            'Ù' | 'Ú' | 'Û' | 'Ü' => 'U',
            'ù' | 'ú' | 'û' | 'ü' => 'u',
            'Ý' | 'Ÿ' => 'Y',
            'ý' | 'ÿ' => 'y',
            'Þ' => 'T',
            'þ' => 't',
            'ß' => 's',
            'Ł' => 'L',
            'ł' => 'l',
            'Ś' | 'Š' => 'S',
            'ś' | 'š' => 's',
            'Ź' | 'Ž' | 'Ż' => 'Z',
            'ź' | 'ž' | 'ż' => 'z',
            'Ć' | 'Č' => 'C',
            'ć' | 'č' => 'c',
            'Ř' => 'R',
            'ř' => 'r',
            'Ň' => 'N',
            'ň' => 'n',
            'Ď' => 'D',
            'ď' => 'd',
            'Ť' => 'T',
            'ť' => 't',
            other => other,
        })
        .collect()
}

fn str_printf_format(fmt: &str, args: &[String]) -> String {
    let mut result = String::new();
    let mut arg_idx = 0usize;
    let chars: Vec<char> = fmt.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '%' && i + 1 < chars.len() {
            let spec = chars[i + 1];
            match spec {
                '%' => {
                    result.push('%');
                    i += 2;
                }
                's' => {
                    if arg_idx < args.len() {
                        result.push_str(&args[arg_idx]);
                        arg_idx += 1;
                    }
                    i += 2;
                }
                'd' => {
                    if arg_idx < args.len() {
                        let v: i64 = args[arg_idx].parse().unwrap_or(0);
                        result.push_str(&v.to_string());
                        arg_idx += 1;
                    }
                    i += 2;
                }
                'f' => {
                    if arg_idx < args.len() {
                        let v: f64 = args[arg_idx].parse().unwrap_or(0.0);
                        result.push_str(&format!("{:.6}", v));
                        arg_idx += 1;
                    }
                    i += 2;
                }
                _ => {
                    result.push(chars[i]);
                    i += 1;
                }
            }
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }
    result
}

fn aggregate(name: &str, values: &[Value]) -> Value {
    let nums: Vec<f64> = values
        .iter()
        .filter_map(|v| match v {
            Value::Float(f) => Some(*f),
            Value::Integer(i) => Some(*i as f64),
            _ => None,
        })
        .collect();

    match name.to_uppercase().as_str() {
        "SUM" => Value::Float(nums.iter().sum()),
        "COUNT" => Value::Integer(values.len() as i64),
        "AVG" => {
            if nums.is_empty() {
                Value::Null
            } else {
                Value::Float(nums.iter().sum::<f64>() / nums.len() as f64)
            }
        }
        "MIN" => nums
            .iter()
            .cloned()
            .reduce(f64::min)
            .map(Value::Float)
            .unwrap_or(Value::Null),
        "MAX" => nums
            .iter()
            .cloned()
            .reduce(f64::max)
            .map(Value::Float)
            .unwrap_or(Value::Null),
        "MEDIAN" => {
            if nums.is_empty() {
                return Value::Null;
            }
            let mut sorted = nums.clone();
            sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            let mid = sorted.len() / 2;
            if sorted.len() % 2 == 0 {
                Value::Float((sorted[mid - 1] + sorted[mid]) / 2.0)
            } else {
                Value::Float(sorted[mid])
            }
        }
        "STDDEV" | "STD_DEV" | "STANDARD_DEVIATION" => {
            if nums.len() < 2 {
                return Value::Null;
            }
            let mean = nums.iter().sum::<f64>() / nums.len() as f64;
            let var =
                nums.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / (nums.len() - 1) as f64;
            Value::Float(var.sqrt())
        }
        "VARIANCE" | "VAR" => {
            if nums.len() < 2 {
                return Value::Null;
            }
            let mean = nums.iter().sum::<f64>() / nums.len() as f64;
            let var =
                nums.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / (nums.len() - 1) as f64;
            Value::Float(var)
        }
        "FIRST" => values.first().cloned().unwrap_or(Value::Null),
        "LAST" => values.last().cloned().unwrap_or(Value::Null),
        "STRING_AGG" => {
            let parts: Vec<String> = values
                .iter()
                .filter_map(|v| match v {
                    Value::String(s) => Some(s.clone()),
                    Value::Integer(i) => Some(i.to_string()),
                    Value::Float(f) => Some(f.to_string()),
                    Value::Bool(b) => Some(b.to_string()),
                    Value::Null => None,
                    _ => None,
                })
                .collect();
            Value::String(parts.join(", "))
        }
        _ => Value::Null,
    }
}

fn bm25_scores_impl(docs: &[String], query_terms: &[String]) -> Vec<f64> {
    let k1 = 1.5f64;
    let b = 0.75f64;
    let n = docs.len();
    if n == 0 || query_terms.is_empty() {
        return vec![0.0; n];
    }

    // Tokenize each document (split on whitespace, lowercase)
    let tokenized: Vec<Vec<String>> = docs
        .iter()
        .map(|doc| doc.split_whitespace().map(|w| w.to_lowercase()).collect())
        .collect();

    // Average document length
    let avg_dl = tokenized.iter().map(|t| t.len()).sum::<usize>() as f64 / n as f64;

    // Precompute document frequency per query term
    let df: Vec<usize> = query_terms
        .iter()
        .map(|term| {
            let t = term.to_lowercase();
            tokenized
                .iter()
                .filter(|tokens| tokens.contains(&t))
                .count()
        })
        .collect();

    tokenized
        .iter()
        .map(|tokens| {
            let dl = tokens.len() as f64;
            query_terms
                .iter()
                .zip(df.iter())
                .map(|(term, &df_t)| {
                    let t = term.to_lowercase();
                    let tf = tokens.iter().filter(|w| *w == &t).count() as f64;
                    if tf == 0.0 {
                        return 0.0;
                    }
                    // IDF (with smoothing to avoid log(0))
                    let idf = ((n as f64 - df_t as f64 + 0.5) / (df_t as f64 + 0.5) + 1.0).ln();
                    let tf_norm = tf * (k1 + 1.0) / (tf + k1 * (1.0 - b + b * dl / avg_dl));
                    idf * tf_norm
                })
                .sum::<f64>()
        })
        .collect()
}
